INSERT INTO chunks_src (id, doc, body, morphemes) VALUES
(1, '재택근무 규정', '재택근무는 입사 6개월이 지난 정규직 직원이 주 2일 이내로 사용할 수 있습니다. 수습 기간 중인 직원과 현장 근무가 필수인 직무는 대상에서 제외됩니다.', ['재택근무', '입사', '6', '지나', '정규직', '직원', '주', '2', '이내', '사용', '수습', '기간', '직원', '현장', '근무', '필수', '직무', '대상', '제외']),
(2, '재택근무 규정', '재택 근무 신청서는 사내 포털의 근태관리 메뉴에서 작성합니다. 근무 희망일과 근무 장소를 입력한 뒤 제출 버튼을 누르면 팀장에게 결재가 올라갑니다.', ['재택', '근무', '신청서', '사내', '포털', '근태', '관리', '메뉴', '작성', '근무', '희망', '일', '근무', '장소', '입력', '뒤', '제출', '버튼', '누르', '팀장', '결재', '올라가']),
(3, '재택근무 규정', 'Q. 재택 근무 신청서를 모바일에서도 작성할 수 있나요? A. 사내 포털 모바일 앱의 근태 메뉴에서도 같은 양식으로 작성하고 제출할 수 있습니다.', ['q.', '재택', '근무', '신청서', '모바일', '작성', 'a.', '사내', '포털', '모바일', '앱', '근', '태', '메뉴', '같', '양식', '작성', '제출']),
(4, '재택근무 규정', '재택근무 승인은 근무 전날 오후 6시까지 팀장이 결재해야 확정됩니다. 당일 신청은 긴급한 사유가 있을 때만 예외로 인정합니다.', ['재택', '근무', '승인', '근무', '전날', '오후', '6', '팀장', '결재', '확정', '당일', '신청', '긴급', '사유', '때', '예외', '인정']),
(5, '재택근무 규정', '재택근무일에도 코어 타임인 오전 10시부터 오후 4시까지는 메신저와 메일에 바로 응답할 수 있어야 합니다.', ['재택근무', '일', '코어', '타임', '오전', '10', '오후', '4', '메신저', '메일', '응답']),
(6, '재택근무 규정', '재택근무에 사용하는 노트북은 회사가 지급한 장비만 허용하며, 개인 PC로는 사내 시스템에 접속할 수 없습니다.', ['재택근무', '사용', '노트북', '회사', '지급', '장비', '허용', '개인', 'pc', '사내', '시스템', '접속', '없']),
(7, '재택근무 규정', '재택근무 중 사내 시스템에 접속할 때는 반드시 VPN을 사용해야 하며, 카페 같은 공용 Wi-Fi에서는 업무 파일을 열지 않아야 합니다.', ['재택', '근무', '사내', '시스템', '접속', '때', 'vpn', '사용', '카페', '같', '공용', 'wi', 'fi', '업무', '파일', '열']),
(8, '재택근무 규정', '재택근무를 마치면 당일 업무 내용을 팀 공유 문서에 정리하고, 퇴근 전에 팀장에게 메신저로 보고합니다.', ['재택', '근무', '마치', '당일', '업무', '내용', '팀', '공유', '문서', '정리', '퇴근', '전', '팀장', '메신저', '보고']),
(9, '재택근무 규정', '재택근무 중 업무와 관련해 다치거나 장비가 고장 난 경우에는 즉시 팀장과 총무팀에 알려야 합니다.', ['재택', '근무', '업무', '관련', '다치', '장비', '고장', '나', '경우', '즉시', '팀장', '총무', '팀', '알리']),
(10, '재택근무 규정', '재택근무 지원금은 월 5만 원이며 통신비와 전기료 명목으로 급여에 합산해 지급합니다. 별도의 증빙 제출은 필요하지 않습니다.', ['재택', '근무', '지원금', '월', '5', '만', '통신비', '전기료', '명목', '급여', '합산', '지급', '별도', '증빙', '제출', '필요']),
(11, '재택근무 규정', '업무 성과가 기준에 못 미치거나 보안 규정을 위반하면 재택근무 허가를 취소할 수 있으며, 취소 사실은 해당 직원에게 서면으로 알립니다.', ['업무', '성과', '기준', '미치', '보안', '규정', '위반', '재택근무', '허가', '취소', '취소', '사실', '해당', '직원', '서면', '알리']),
(12, '연차·휴가 규정', '연차 휴가는 1년간 80% 이상 출근한 직원에게 15일이 발생하며, 3년 이상 근속하면 2년마다 1일씩 가산되어 최대 25일까지 늘어납니다.', ['연차', '휴가', '1', '80', '이상', '출근', '직원', '15', '발생', '3', '이상', '근속', '2', '1', '가산', '최대', '25', '늘어나']),
(13, '연차·휴가 규정', '입사 1년 미만 직원의 연차 휴가는 한 달을 개근할 때마다 1일씩 발생하고, 입사 첫해에는 최대 11일까지 사용할 수 있습니다.', ['입사', '1', '미만', '직원', '연차', '휴가', '달', '개근', '때', '1', '발생', '입사', '첫해', '최대', '11', '사용']),
(14, '연차·휴가 규정', '연차는 사용 3일 전까지 근태 시스템에서 신청하고 팀장 승인을 받아야 합니다. 3일 이상 연속으로 쓸 때는 업무 인수인계서를 함께 첨부합니다.', ['연차', '사용', '3', '전', '근태', '시스템', '신청', '팀장', '승인', '받', '3', '이상', '연속', '쓰', '때', '업무', '인수인계', '서', '첨부']),
(15, '연차·휴가 규정', '반차는 오전(9시~13시)과 오후(14시~18시)로 나누어 사용하며 0.5일로 차감됩니다. 오전 반차와 오후 반차를 이어서 쓰면 연차 1일로 계산합니다.', ['반', '차', '오전', '9', '13', '오후', '14', '18', '나누', '사용', '0.5', '차감', '오전', '반', '차', '오후', '반', '차', '잇', '쓰', '연차', '1', '계산']),
(16, '연차·휴가 규정', '이미 승인된 연차의 취소는 근태 시스템의 \'내 신청 내역\'에서 취소 요청을 올려 처리하며, 휴가 시작 전날 18시까지 가능합니다.', ['승인', '연차', '취소', '근태', '시스템', '신청', '내역', '취소', '요청', '올리', '처리', '휴가', '시작', '전날', '18', '가능']),
(17, '연차·휴가 규정', '휴가 당일이나 시작 이후의 취소는 팀장 승인이 필요하고, 취소한 연차는 즉시 잔여 일수에 되돌려집니다.', ['휴가', '당일', '시작', '이후', '취소', '팀장', '승인', '필요', '취소', '연차', '즉시', '잔여', '일수', '되돌리']),
(18, '연차·휴가 규정', '병가는 연 10일까지 유급으로 사용할 수 있고, 3일 이상 연속될 때는 의사 진단서를 제출해야 합니다.', ['병가', '연', '10', '유급', '사용', '3', '이상', '연속', '때', '의사', '진단서', '제출']),
(19, '연차·휴가 규정', '경조 휴가 일수는 규정집의 경조 휴가 표에 따라 부여하며, 결혼·출산·상 등 사유별 증빙 서류는 복귀 후 3일 이내에 제출해야 합니다.', ['경조', '휴가', '일수', '규정', '집', '경조', '휴가', '표', '따르', '부여', '결혼', '출산', '상', '사유', '증빙', '서류', '복귀', '후', '3', '이내', '제출']),
(20, '연차·휴가 규정', '남은 연차 일수는 사내 포털의 근태 메뉴에서 \'내 연차 현황\'을 눌러 확인할 수 있습니다.', ['남', '연차', '일수', '사내', '포털', '태', '메뉴', '연차', '현황', '누르', '확인']),
(21, '연차·휴가 규정', '연말까지 사용하지 못한 연차는 다음 해 1월에 미사용 수당으로 정산해 급여와 함께 지급합니다.', ['연말', '사용', '연차', '다음', '해', '1', '미', '사용', '수당', '정산', '급여', '지급']),
(22, '연차·휴가 규정', '공휴일과 겹치는 휴가 기간은 연차에서 차감하지 않으며, 주말을 사이에 둔 연속 휴가는 휴일을 제외하고 계산합니다.', ['공휴일', '겹치', '휴가', '기간', '연차', '차감', '주말', '사이', '두', '연속', '휴가', '휴일', '제외', '계산']),
(23, '출장 규정', '출장은 출발 3영업일 전까지 출장 신청서를 작성해 팀장의 승인을 받아야 합니다. 해외 출장은 본부장 승인이 추가로 필요합니다.', ['출장', '출발', '3', '영업일', '전', '출장', '신청서', '작성', '팀장', '승인', '받', '해외', '출장', '본부장', '승인', '추가', '필요']),
(24, '출장 규정', '출장비는 출발 3영업일 전까지 가지급을 신청하면 출발 전날 급여 계좌로 먼저 지급됩니다. 가지급 신청은 출장 신청서의 \'가지급\' 칸에 체크하면 됩니다.', ['출장비', '출발', '3', '영업일', '전', '지급', '신청', '출발', '전날', '급여', '계좌', '지급', '지급', '신청', '출장', '신청서', '가지급', '칸', '체크']),
(25, '출장 규정', '출장비가 50만 원을 넘는 가지급은 재무팀장의 추가 승인이 있어야 지급되며, 승인이 늦어지면 출발일 이후에 지급될 수 있습니다.', ['출장비', '50', '만', '넘', '지급', '재무', '팀장', '추가', '승인', '지급', '승인', '늦', '출발', '이후', '지급']),
(26, '출장 규정', '출장지별 일비 금액은 규정집 부록의 일비 표를 기준으로 합니다. 이 표가 매년 1월에 개정되어 사내 포털에 게시됩니다.', ['출장지', '일비', '금액', '규정', '부록', '일비', '표', '기준', '표', '1', '개정', '사내', '포털', '게시']),
(27, '출장 규정', '일비 표를 찾기 어려우면 총무팀 포털 게시판의 \'출장 안내\' 글에서도 같은 표를 내려받을 수 있습니다.', ['일비', '표', '찾', '어렵', '총무', '팀', '포털', '게시판', '출장', '안내', '글', '같', '표', '내리', '받']),
(28, '출장 규정', '숙박비는 1박 기준 서울 15만 원, 그 밖의 국내 지역 12만 원까지 실비로 인정하며 영수증을 첨부해야 합니다.', ['숙박비', '1', '기준', '서울', '15', '만', '밖', '국내', '지역', '12', '만', '실비', '인정', '영수증', '첨부']),
(29, '출장 규정', 'KTX와 항공권은 출장 신청이 승인된 뒤 법인 계정으로 예약하는 것을 원칙으로 하며, 일반실과 이코노미석만 인정합니다.', ['ktx', '항공', '출장', '신청', '승인', '뒤', '법인', '계정', '예약', '원칙', '일반', '실', '이코노미', '석', '인정']),
(30, '출장 규정', '해외 출장자는 출발 전에 해외 여행자 보험 가입과 로밍 신청을 마쳐야 하고, 여권 사본을 총무팀에 제출합니다.', ['해외', '출장', '출발', '전', '해외', '여행자', '보험', '가입', '로밍', '신청', '마치', '여권', '사본', '총무', '팀', '제출']),
(31, '출장 규정', '복귀 후에는 출장비를 7일 이내에 정산하고, 출장 결과 보고서를 함께 제출해야 합니다. 기한을 넘기면 다음 출장 신청이 제한될 수 있습니다.', ['복귀', '후', '출장비', '7', '이내', '정산', '출장', '결과', '보고서', '제출', '기한', '넘기', '다음', '출장', '신청', '제한']),
(32, '출장 규정', '개인 차량으로 출장을 가면 km당 200원의 유류비를 지급하며, 통행료는 영수증을 제출할 때 실비로 지급합니다.', ['개인', '차량', '출장', '가', 'km', '200', '유류', '비', '지급', '통행료', '영수증', '제출', '때', '실비', '지급']),
(33, '출장 규정', '출장이 취소되면 가지급받은 출장비를 3일 이내에 반납하고, 근태 시스템에서 출장 신청도 함께 취소합니다.', ['출장', '취소', '지급', '받', '출장비', '3', '이내', '반납', '근태', '시스템', '출장', '신청', '취소']),
(34, '경비 정산·법인카드', '개인 비용을 법인카드 대신 사비로 결제한 경우에는 결제일로부터 30일 이내에 경비 정산 시스템에 등록해야 합니다.', ['개인', '비용', '법인', '카드', '대신', '사비', '결제', '경우', '결제', '일', '30', '이내', '경비', '정산', '시스템', '등록']),
(35, '경비 정산·법인카드', '경비를 정산할 때는 영수증을 원본 그대로 스캔해 첨부하고, 지출 목적과 참석자를 적요란에 입력합니다.', ['경비', '정산', '때', '영수증', '원본', '스캔', '첨부', '지출', '목적', '참석자', '적', '요', '란', '입력']),
(36, '경비 정산·법인카드', '영수증이 없을 때는 지출 증빙 사유서를 작성해 팀장 서명을 받으면 정산할 수 있습니다. 단, 건당 3만 원을 넘는 지출은 사유서만으로 인정되지 않습니다.', ['영수증', '없', '때', '지출', '증빙', '사유서', '작성', '팀장', '서명', '받', '정산', '3', '만', '넘', '지출', '사유서', '인정']),
(37, '경비 정산·법인카드', '카드 단말기에서 영수증은 재출력이 가능하므로 결제한 가맹점에 연락해 재발행을 요청하고, 어려우면 카드사 홈페이지의 매출전표를 출력해 첨부합니다.', ['카드', '단말기', '영수증', '출력', '가능', '결제', '가맹점', '연락', '발행', '요청', '어렵', '카드사', '홈페이지', '매출', '전표', '출력', '첨부']),
(38, '경비 정산·법인카드', '법인카드 한도 상향은 한도 상향 신청서를 작성해 팀장 결재를 받은 뒤 재무팀에 제출하면 처리됩니다.', ['법인', '카드', '한도', '상향', '한도', '상향', '신청서', '작성', '팀장', '결재', '받', '뒤', '재무', '팀', '제출', '처리']),
(39, '경비 정산·법인카드', '임시 상향이 필요하면 신청서에 출장·행사 일정과 예상 사용 금액을 사유로 적습니다. 임시 상향은 다음 영업일에 반영되어 30일 뒤 법인카드 한도가 원래 금액으로 돌아옵니다.', ['임시', '상향', '필요', '신청', '서', '출장', '행사', '일정', '예상', '사용', '금액', '사유', '적', '임시', '상향', '다음', '영업일', '반영', '30', '뒤', '법인', '카드', '한도', '원래', '금액', '돌아오']),
(40, '경비 정산·법인카드', '법인카드 분실 시에는 즉시 카드사 고객센터에 사용 정지를 요청한 뒤, 재무팀에 분실 신고서를 제출해야 합니다. 신고 전에 발생한 부정 사용은 본인이 책임질 수 있습니다.', ['법인', '카드', '분실', '즉시', '카드사', '고객', '센터', '사용', '정지', '요청', '뒤', '재무', '팀', '분실', '신고서', '제출', '신고', '전', '발생', '부정', '사용', '본인', '책임지']),
(41, '경비 정산·법인카드', '법인카드는 유흥업소, 면세점, 상품권 구매 등 제한 업종에서는 결제가 차단되며, 업무상 필요하면 사전에 재무팀과 협의합니다.', ['법인', '카드', '유흥', '업소', '면세점', '상품', '구매', '제한', '업종', '결제', '차단', '업무', '필요', '사전', '재무', '팀', '협의']),
(42, '경비 정산·법인카드', '거래처 접대비는 1인당 5만 원을 초과할 수 없고, 참석자의 소속과 성명을 정산 시스템에 반드시 입력해야 합니다.', ['거래처', '접대비', '1', '인', '5', '만', '초과', '없', '참석자', '소속', '성명', '정산', '시스템', '입력']),
(43, '경비 정산·법인카드', '연장 근무 식대는 1인당 1만 5천 원 이내에서 정산하며, 법인카드가 없는 경우 개인 카드로 결제한 뒤 청구합니다.', ['연장', '근무', '식대', '1', '인', '1', '만', '5', '천', '이내', '정산', '법인', '카드', '없', '경우', '개인', '카드', '결제', '뒤', '청구']),
(44, '경비 정산·법인카드', '정산이 승인되면 다음 주 수요일에 급여 계좌로 입금되며, 반려된 건은 사유를 확인해 다시 상신해야 합니다.', ['정산', '승인', '다음', '주', '수요일', '급여', '계좌', '입금', '반려', '건', '사유', '확인', '상', '신']),
(45, '경비 정산·법인카드', '해외에서 법인카드를 쓸 때는 출국 전에 해외 결제 허용을 신청해야 하고, 환율은 결제일 기준 카드사 고시 환율을 적용합니다.', ['해외', '법인', '카드', '쓰', '때', '출국', '전', '해외', '결제', '허용', '신청', '환율', '결제', '기준', '카드사', '고시', '환율', '적용']),
(46, '교육 지원 제도', '직원은 연간 100만 원 한도 내에서 직무 관련 사외 교육비를 지원받을 수 있으며, 팀장이 교육의 직무 연관성을 승인해야 합니다.', ['직원', '연간', '100', '만', '한도', '직무', '관련', '사외', '교육비', '지원', '팀장', '교육', '직무', '연관', '승인']),
(47, '교육 지원 제도', '사외 교육 신청 마감은 교육 시작일 2주 전이며, 마감 후에는 지원 대상에서 제외될 수 있으니 일정에 맞춰 신청해야 합니다.', ['사외', '교육', '신청', '마감', '교육', '시작', '2', '전', '마감', '후', '지원', '대상', '제외', '일정', '맞추', '신청']),
(48, '교육 지원 제도', '사내 집합 교육 신청은 매월 25일에 다음 달 교육 과정이 공지되고, 공지일부터 10일 이내에 접수할 수 있습니다.', ['사내', '집합', '교육', '신청', '25', '다음', '달', '교육', '과정', '공지', '공지', '10', '이내', '접수']),
(49, '교육 지원 제도', '어학, 자격증, 온라인 강의 중 직무와 관련 없는 과정은 지원 대상에서 제외되며, 교육 신청 전에 이미 결제한 교육비는 환급되지 않습니다.', ['어학', '자격증', '온라인', '강의', '직무', '관련', '없', '과정', '지원', '대상', '제외', '교육', '신청', '전', '결제', '교육비', '환급']),
(50, '교육 지원 제도', '외부 교육을 수료한 뒤 7일 이내에 수료증과 수강료 영수증을 교육 지원 게시판에 올리면 수강료 환급이 진행됩니다.', ['외부', '교육', '수료', '뒤', '7', '이내', '수료증', '수강료', '영수증', '교육', '지원', '게시판', '올리', '수강료', '환급', '진행']),
(51, '교육 지원 제도', '수료 후 환급금은 다음 달 급여와 함께 지급되며, 교육 수료 여부는 교육기관이 발급한 수료증으로만 확인합니다.', ['수료', '후', '환급금', '다음', '달', '급여', '지급', '교육', '수료', '여부', '교육', '기관', '발급', '수료증', '확인']),
(52, '교육 지원 제도', '교육을 끝까지 마치지 못하면 환급받은 교육비의 50%를 회수하며, 질병 등 불가피한 사유는 증빙 후 면제됩니다.', ['교육', '끝', '마치', '환급', '받', '교육비', '50', '르', '회수', '질병', '불가피', '사유', '증빙', '후', '면제']),
(53, '교육 지원 제도', '출석률이 80% 미만이면 수료로 인정되지 않아 교육비 지원 대상에서 제외되며, 이미 지급된 금액은 회수될 수 있습니다.', ['출석', '80', '미만', '수료', '인정', '교육비', '지원', '대상', '제외', '지급', '금액', '회수']),
(54, '교육 지원 제도', '사내 강사로 교육을 진행하면 시간당 5만 원의 강사료를 지급하며, 교육 자료는 학습 포털에 등록해야 합니다.', ['사내', '강사', '교육', '진행', '시간', '5', '만', '강사', '료', '지급', '교육', '자료', '학습', '포털', '등록']),
(55, '교육 지원 제도', '직무 도서는 월 3만 원까지 구입비를 지원하며 구입 영수증과 도서명을 경비 정산 시스템에 등록합니다.', ['직무', '도서', '월', '3', '만', '구입비', '지원', '구입', '영수증', '도서', '명', '경비', '정산', '시스템', '등록']),
(56, '교육 지원 제도', '개인정보 보호와 정보보안 교육은 연 1회 전 직원이 필수로 이수해야 하며, 미이수자에게는 인사 평가에서 불이익이 있을 수 있습니다.', ['개인', '정보', '보호', '정보', '보안', '교육', '연', '1', '직원', '필수', '이수', '이수자', '인사', '평가', '이익']),
(57, '사원증·출입 안내', '사원증은 입사 첫날 인사팀에서 발급하며, 증명사진은 입사 전에 사내 포털에 등록해 두어야 합니다.', ['사원증', '입사', '첫날', '인사', '팀', '발급', '증명사진', '입사', '전', '사내', '포털', '등록']),
(58, '사원증·출입 안내', '방문자는 방문 1일 전까지 방문 예약 시스템에서 담당 직원이 사전 등록해야 하며, 당일 등록은 보안팀 승인이 있어야 가능합니다.', ['방문자', '방문', '1', '전', '방문', '예약', '시스템', '담당', '직원', '사전', '등록', '당일', '등록', '보안', '팀', '승인', '가능']),
(59, '사원증·출입 안내', '등록할 때는 방문자의 이름, 소속, 방문 목적, 차량 번호를 입력해야 하며, 입력한 정보가 신분증과 다르면 출입이 제한될 수 있습니다.', ['등록', '때', '방문자', '이름', '소속', '방문', '목적', '차량', '번호', '입력', '입력', '정보', '신분증', '다르', '출입', '제한']),
(60, '사원증·출입 안내', '방문자가 도착하면 1층 안내 데스크에서 신분증을 확인한 뒤 일회용 방문증을 발급하고, 등록한 담당 직원이 로비로 내려와 동행합니다.', ['방문자', '도착', '1', '층', '안내', '데스크', '신분증', '확인', '뒤', '일', '방문', '증', '발급', '등록', '담당', '직원', '로비', '내려오', '동행']),
(61, '사원증·출입 안내', '방문자를 동반한 직원은 방문 시간 동안 방문자 곁을 떠나서는 안 되며, 방문증은 퇴실 시 안내 데스크에 반납합니다.', ['방문자', '동반', '직원', '방문', '시간', '동안', '방문자', '곁', '떠나', '방문', '증', '퇴실', '시', '안내', '데스크', '반납']),
(62, '사원증·출입 안내', '출입 키는 총무팀에서 재발급하며, 사원증을 지참하고 방문하면 당일 발급됩니다. 재발급 비용은 첫 1회에 한해 무료입니다.', ['출입', '키', '총무', '팀', '발급', '사원', '증', '지참', '방문', '당일', '발급', '발급', '비용', '1', '한', '무료']),
(63, '사원증·출입 안내', '출입 키가 훼손되었거나 인식되지 않을 때도 총무팀에서 교체해 주며, 기존 키는 반납해야 새 키가 활성화됩니다.', ['출입', '키', '훼손', '인식', '때', '총무', '팀', '교체', '기존', '키', '반납', '키', '활성']),
(64, '사원증·출입 안내', '사원증을 분실하면 즉시 보안팀에 신고하고 재발급 신청서를 제출해야 하며, 재발급까지는 임시 출입증으로 근무합니다.', ['사원', '증', '분실', '즉시', '보안', '팀', '신고', '발급', '신청서', '제출', '발급', '임시', '출입증', '근무']),
(65, '사원증·출입 안내', '야간(22시~06시)과 주말 출입은 사전에 팀장 승인을 받은 직원만 가능하며, 승인 내역은 보안팀이 매일 확인합니다.', ['야간', '22', '06', '주말', '출입', '사전', '팀장', '승인', '받', '직원', '가능', '승인', '내역', '보안', '팀', '확인']),
(66, '사원증·출입 안내', '서버실과 연구소는 출입 권한이 별도로 부여된 직원만 들어갈 수 있고, 권한은 부서장이 신청합니다.', ['서버', '실', '연구소', '출입', '권한', '별도', '부여', '직원', '들어가', '권한', '부서장', '신청']),
(67, '사원증·출입 안내', '출입문 단말기에 사원증을 대도 열리지 않으면 보안팀에 연락하고, 문을 억지로 열거나 다른 사람의 사원증을 빌려 쓰면 안 됩니다.', ['출입문', '단말기', '사원', '증', '열리', '보안', '팀', '연락', '문', '열', '사람', '사원', '증', '빌리', '쓰']),
(68, '회의실 예약', '회의실은 사내 포털의 \'자원 예약\' 메뉴에서 시간 단위로 예약하며, 한 번에 연속으로 예약할 수 있는 시간은 최대 4시간입니다.', ['회의실', '사내', '포털', '자원', '예약', '메뉴', '시간', '단위', '예약', '연속', '예약', '시간', '최대', '4']),
(69, '회의실 예약', '회의실이 급하게 필요하면 사내 포털 모바일 앱의 \'자원 예약\'에서도 예약할 수 있고, 예약을 마치면 캘린더 초대가 참석자에게 자동으로 발송됩니다.', ['회의실', '급하', '필요', '사내', '포털', '모바일', '앱', '자원', '예약', '예약', '예약', '마치', '캘린더', '초대', '참석', '자동', '발송']),
(70, '회의실 예약', '본관 3층은 대회의실, 4층은 중회의실, 5층은 소회의실 구역입니다. 엘리베이터 앞에 회의실 배치도가 붙어 있습니다.', ['본관', '3', '층', '회의실', '4', '층', '중', '회의실', '5', '층', '회의실', '구역', '엘리베이터', '앞', '회의실', '배치도', '붙']),
(71, '회의실 예약', '별관 3층은 8인 규모의 소회의실 두 곳이 있는 층이며, 별관과 본관은 4층 연결 통로로 오갈 수 있습니다.', ['별관', '3', '층', '8', '인', '규모', '회의실', '곳', '층', '별관', '본관', '4', '층', '연결', '통로', '오가']),
(72, '회의실 예약', '예약한 회의실을 쓰지 않을 때는 시작 전에 예약을 취소해야 하며, 시작 10분이 지나도 입실하지 않으면 예약이 자동으로 해제됩니다.', ['예약', '회의실', '쓰', '때', '시작', '전', '예약', '취소', '시작', '10', '지나', '입', '실', '예약', '자동', '해제']),
(73, '회의실 예약', '3회 이상 무단으로 예약을 사용하지 않은 직원은 한 달간 회의실 예약이 제한되며, 제한 기간이 끝나면 다시 예약할 수 있습니다.', ['3', '이상', '무단', '예약', '사용', '직원', '달', '간', '회의실', '예약', '제한', '제한', '기간', '끝나', '예약']),
(74, '회의실 예약', '회의가 끝나면 화이트보드를 지우고 음식물과 쓰레기는 가져가며, 의자와 테이블을 처음 배치대로 정리해야 합니다.', ['회의', '끝나', '화이트보드', '지우', '음식물', '쓰레기', '가져가', '의자', '테이블', '처음', '배치', '정리']),
(75, '회의실 예약', '화상회의 장비는 회의실 벽면의 HDMI 케이블을 노트북에 연결하면 화면이 자동으로 전환되며, 카메라와 마이크는 별도 설정 없이 사용할 수 있습니다.', ['화상', '회의', '장비', '회의실', '벽면', 'hdmi', '케이블', '노트북', '연결', '화면', '자동', '전환', '카메라', '마이크', '별도', '설정', '사용']),
(76, '회의실 예약', '무선 화면 공유가 필요하면 회의실 TV 하단의 안내 QR을 노트북으로 스캔해 연결할 수 있으며, 화상회의 마이크는 TV 상단의 스피커에 내장되어 있습니다.', ['무선', '화면', '공유', '필요', '회의실', 'tv', '하단', '안내', 'qr', '노트북', '스캔', '연결', '화상', '회의', '마이크', 'tv', '상단', '스피커', '내장']),
(77, '회의실 예약', '외부 손님과 회의할 때는 1층 접견실을 우선 사용하고, 접견실을 쓸 수 없을 때만 본관 회의실을 예약합니다.', ['외부', '손님', '회의', '때', '1', '층', '접견실', '사용', '접견실', '쓰', '없', '때', '본관', '회의실', '예약']),
(78, '회의실 예약', '화상회의 녹화는 사전에 참석자 전원의 동의를 받은 경우에만 허용하며, 녹화 파일은 사내 드라이브에만 저장해야 합니다.', ['화상', '회의', '녹화', '사전', '참석자', '전원', '동의', '받', '경우', '허용', '녹화', '파일', '사내', '드라이브', '저장']),
(79, '회의실 예약', '회의실 에어컨이나 조명이 작동하지 않으면 총무팀 헬프데스크에 회의실 번호와 증상을 알려 주세요.', ['회의실', '에어컨', '조명', '작동', '총무', '팀', '헬프데스크', '회의실', '번호', '증상', '알리']),
(80, '법인 차량 이용', '법인 차량은 사내 포털의 \'차량 배차\' 메뉴에서 이용 신청을 하며, 운행 하루 전 정오까지 접수해야 합니다.', ['법인', '차량', '사내', '포털', '차량', '배차', '메뉴', '이용', '신청', '운행', '하루', '전', '정오', '접수']),
(81, '법인 차량 이용', '법인 차량 이용 신청 시에는 운행 목적, 목적지, 동승자 명단을 입력하고, 배차가 확정되면 문자로 차량 번호와 주차 위치를 알려 드립니다.', ['법인', '차량', '이용', '신청', '운행', '목적', '목적지', '동승', '명단', '입력', '배차', '확정', '문자', '차량', '번호', '주차', '위치', '알리']),
(82, '법인 차량 이용', '법인 차량은 운전면허를 취득한 지 1년이 지난 직원만 운전할 수 있으며, 면허증 사본을 총무팀에 미리 제출해야 합니다.', ['법인', '차량', '운전', '면허', '취득', '1', '지나', '직원', '운전', '면허증', '사본', '총무', '팀', '제출']),
(83, '법인 차량 이용', '법인 차가 사고를 당하면 먼저 인명 피해를 확인하고 119와 경찰에 신고한 뒤, 총무팀에 즉시 연락합니다.', ['법인', '차', '사고', '당하', '인명', '피해', '확인', '119', '경찰', '신고', '뒤', '총무', '팀', '즉시', '연락']),
(84, '법인 차량 이용', '법인 차는 종합보험에 가입되어 있어 사고 처리는 총무팀이 보험사와 진행하며, 운전자는 사고 경위서를 작성해 제출합니다.', ['법인', '차', '종합', '보험', '가입', '사고', '처리', '총무', '팀', '보험사', '진행', '운전자', '사고', '경위', '서', '작성', '제출']),
(85, '법인 차량 이용', '법인 차량 운행 중 발생한 교통 법규 위반 과태료는 운전자가 부담하며, 고지서는 총무팀을 거쳐 본인에게 전달됩니다.', ['법인', '차량', '운행', '발생', '교통', '법규', '위반', '과태료', '운전자', '부담', '고지서', '총무', '팀', '거치', '본인', '전달']),
(86, '법인 차량 이용', '주유는 차량에 비치된 법인 주유카드로만 하며, 주유 영수증은 차량 일지와 함께 총무팀에 제출합니다.', ['주유', '차량', '비치', '법인', '주유', '카드', '주유', '영수증', '차량', '일지', '총무', '팀', '제출']),
(87, '법인 차량 이용', '운행이 끝나면 지정된 주차 구역에 차량을 반납하고, 주행 거리와 연료량을 차량 일지에 기록한 뒤 키를 총무팀 키 보관함에 넣습니다.', ['운행', '끝나', '지정', '주차', '구역', '차량', '반납', '주행', '거리', '연료', '량', '차량', '일지', '기록', '뒤', '키', '총무', '팀', '키', '보관', '함', '넣']),
(88, '법인 차량 이용', '운행 전에는 타이어, 오일, 외관을 점검하고 이상이 있으면 사진을 찍어 총무팀에 알려야 합니다.', ['운행', '전', '타이어', '오일', '외관', '점검', '이상', '사진', '찍', '총무', '팀', '알리']),
(89, '법인 차량 이용', '법인 차를 개인 용무로 사용하는 것은 금지되며, 적발되면 연료비와 감가 비용을 변상해야 합니다.', ['법인', '차', '개인', '용무', '사용', '금지', '적발', '연료비', '감가', '비용', '변상']),
(90, '법인 차량 이용', '연속 운행은 4시간을 넘기지 않아야 하고, 장거리 출장에는 운전자를 2명 이상 배정하는 것을 권장합니다.', ['연속', '운행', '4', '넘기', '장거리', '출장', '운전자', '2', '이상', '배정', '권장']),
(91, '사무용품 신청', '사무용품은 사내 포털의 \'총무 > 사무용품 신청\' 메뉴에서 신청하며, 신청 건은 매주 목요일에 부서로 일괄 지급합니다.', ['사무', '용품', '사내', '포털', '총무', '사무', '용품', '신청', '메뉴', '신청', '신청', '건', '목요일', '부서', '일괄', '지급']),
(92, '사무용품 신청', '급하게 필요한 사무용품은 본관 비품실에서 직접 받아 갈 수 있고, 수령 내역은 비품실 단말기에 사원증을 대어 기록합니다.', ['급하', '필요', '사무', '용품', '본관', '비품', '실', '받', '수령', '내역', '비품실', '단말기', '사원증', '대', '기록']),
(93, '사무용품 신청', '사무용품 월 지급 한도는 1인당 2만 원이며, 사용하지 않은 한도는 다음 달로 이월되지 않습니다.', ['사무', '용품', '월', '지급', '한도', '1', '인', '2', '만', '사용', '한도', '다음', '달', '이월']),
(94, '사무용품 신청', '명함은 입사 후 첫 주에 신청하면 영업일 기준 5일 뒤에 받을 수 있으며, 직함이나 연락처가 바뀌면 인사 시스템 변경 후 다시 신청해야 합니다.', ['명함', '입사', '후', '주', '신청', '영업일', '기준', '5', '뒤', '받', '직함', '연락처', '바뀌', '인사', '시스템', '변경', '후', '신청']),
(95, '사무용품 신청', '법인 인감과 직인은 총무팀장이 보관하며, 사용하려면 날인 요청서를 작성해 사용 목적과 문서 이름을 기록해야 합니다.', ['법인', '인감', '직인', '총무', '팀장', '보관', '사용', '날인', '요청서', '작성', '사용', '목적', '문서', '이름', '기록']),
(96, '사무용품 신청', '사무용품 재고 현황은 비품실 입구의 안내판과 사내 포털의 \'비품 재고\' 화면에서 확인할 수 있으며, 재고가 없으면 입고 예정일이 함께 표시됩니다.', ['사무', '용품', '재고', '현황', '비품실', '입구', '안내판', '사내', '포털', '품', '재고', '화면', '확인', '재고', '없', '입고', '예정일', '표시']),
(97, '사무용품 신청', '사용하지 않는 용품이나 고장 난 비품은 임의로 버리지 말고 총무팀에 폐기 요청을 올려야 합니다.', ['사용', '용품', '고장', '나', '비품', '임의', '버리', '총무', '팀', '폐기', '요청', '올리']),
(98, '사무용품 신청', '퇴직하거나 부서를 옮길 때는 지급받은 사무용품과 비품(IT 장비는 제외)을 총무팀에 반납하고 확인서를 받아야 합니다.', ['퇴직', '부서', '옮기', '때', '지급', '받', '사무', '용품', '비품', 'it', '장비', '제외', '총무', '팀', '반납', '확인서', '받']),
(99, '사무용품 신청', '개인이 임의로 구입한 용품은 경비로 정산하지 않으며, 사전 승인 없이 구입한 비용은 본인이 부담해야 합니다.', ['개인', '임의', '구입', '용품', '경비', '정산', '사전', '승인', '구입', '비용', '본인', '부담']),
(100, '사무용품 신청', '책상 서랍 열쇠를 분실하면 총무팀에서 잠금장치를 교체하며, 교체 비용은 부서 경비로 처리합니다.', ['책상', '서랍', '열쇠', '분실', '총무', '팀', '잠금장치', '교체', '교체', '비용', '부서', '경비', '처리']),
(101, '사무용품 신청', '개인정보나 기밀이 담긴 종이 문서는 일반 쓰레기통에 버리지 말고 사무실마다 비치된 파쇄함에 넣어야 하며, 파쇄함이 가득 차면 총무팀에 수거를 요청합니다.', ['개인', '정보', '기밀', '담기', '종이', '문서', '일반', '쓰레기통', '버리', '사무실', '비치', '파쇄', '함', '넣', '파쇄', '차', '총무', '팀', '수거', '요청']),
(102, '구매요청서·구매 절차', '구매요청서는 ERP의 \'구매 > 요청\' 화면에서 작성하며, 품목, 수량, 예상 단가, 납품 희망일, 구매 사유를 모두 입력해야 합니다.', ['구매', '요청서', 'erp', '구매', '요청', '화면', '작성', '품목', '수량', '예상', '단가', '납품', '희망', '일', '구매', '사유', '입력']),
(103, '구매요청서·구매 절차', '구매요청서 서식은 사내 포털 서식 보관함에서도 내려받을 수 있지만, 10만 원 미만의 소액 건만 서면으로 제출할 수 있습니다.', ['구매', '요청서', '서식', '사내', '포털', '서식', '보관', '함', '내려받', '10', '만', '미만', '소액', '서면', '제출']),
(104, '구매요청서·구매 절차', '구매요청서는 팀장, 재무팀장 순으로 결재하며, 금액에 따라 승인 단계가 달라집니다. 결재 현황은 ERP에서 실시간으로 확인할 수 있습니다.', ['구매', '요청서', '팀장', '재무', '팀장', '순', '결재', '금액', '따르', '승인', '단계', '달라지', '결재', '현황', 'erp', '실시간', '확인']),
(105, '구매요청서·구매 절차', '100만 원 이상 구매요청서에는 견적서 2부를 첨부해야 하고, 1,000만 원 이상은 3개 업체의 비교 견적이 필요합니다.', ['100', '만', '이상', '구매', '요청서', '견적서', '2', '첨부', '1,000', '만', '이상', '3', '업체', '비교', '견적', '필요']),
(106, '구매요청서·구매 절차', '10만 원 미만은 팀장 전결, 100만 원 미만은 재무팀장, 1,000만 원 이상은 대표이사 승인을 받아야 구매 절차가 시작됩니다.', ['10', '만', '미만', '팀장', '전결', '100', '만', '미만', '재무', '팀장', '1,000', '만', '이상', '대표', '이사', '승인', '받', '구매', '절차', '시작']),
(107, '구매요청서·구매 절차', '승인이 끝나면 구매팀이 3영업일 안에 업체에 발주하며, 발주 번호는 요청자에게 메일로 안내합니다.', ['승인', '끝나', '구매', '팀', '3', '영업일', '안', '업체', '발주', '발주', '번호', '요청', '메일', '안내']),
(108, '구매요청서·구매 절차', '물품이 납품되면 요청자가 규격과 수량을 확인하고 ERP에서 검수 완료를 눌러야 대금이 지급됩니다.', ['물품', '납품', '청자', '규격', '수량', '확인', 'erp', '검수', '완료', '누르', '대금', '지급']),
(109, '구매요청서·구매 절차', '긴급 구매는 사유서를 첨부하면 승인 단계를 줄일 수 있으나, 사후 정산이 필요한 경우는 월 3회로 제한합니다.', ['긴급', '구매', '사유', '서', '첨부', '승인', '단계', '줄이', '사후', '정산', '필요', '경우', '월', '3', '제한']),
(110, '구매요청서·구매 절차', '동일 품목을 승인 한도를 피하려고 나누어 구매하는 분할 구매는 금지되며, 적발되면 구매 담당자가 소명해야 합니다.', ['동일', '품목', '승인', '한도', '피하', '나누', '구매', '분할', '구매', '금지', '적발', '구매', '담당자', '소명']),
(111, '구매요청서·구매 절차', '신규 거래 업체는 사업자등록증과 통장 사본을 제출해 업체 등록을 마친 뒤에만 발주할 수 있습니다.', ['신규', '거래', '업체', '사업자', '등록증', '통장', '사본', '제출', '업체', '등록', '마치', '뒤', '발주']),
(112, '구매요청서·구매 절차', '소프트웨어 라이선스 구매요청서에는 사용 인원과 구독 기간을 적어야 하며, IT팀의 보안 검토 결과가 부적합이면 발주되지 않습니다.', ['소프트웨어', '라이선스', '구매', '요청서', '사용', '인원', '구독', '기간', '적', 'it', '팀', '보안', '검토', '결과', '적합', '발주']),
(113, '전자결재·결재선', '전자결재는 사내 포털의 \'전자결재\' 메뉴에서 기안, 상신, 승인, 반려를 모두 처리하며, 종이 문서는 원칙적으로 사용하지 않습니다.', ['전자', '결재', '사내', '포털', '전자', '결재', '메뉴', '기안', '상신', '승인', '반려', '처리', '종이', '문서', '원칙', '사용']),
(114, '전자결재·결재선', '기안 화면에서 결재선은 기본값으로 소속 부서장까지 지정되어 있으며, 변경하려면 화면 오른쪽의 \'변경\' 버튼을 눌러 결재자를 추가하거나 삭제합니다.', ['기안', '화면', '결재', '선', '기본', '값', '소속', '부서장', '지정', '변경', '화면', '오른쪽', '변경', '버튼', '누르', '결재', '추가', '삭제']),
(115, '전자결재·결재선', '이미 상신한 문서의 결재선이 잘못되었다면 첫 결재자가 승인하기 전에 회수한 뒤 수정하여 다시 상신해야 하며, 첫 결재자가 승인한 뒤에는 변경할 수 없습니다.', ['상신', '문서', '결재', '선', '결재', '승인', '전', '회수', '뒤', '수정', '상', '신', '결재', '승인', '뒤', '변경', '없']),
(116, '전자결재·결재선', '문서를 반려받으면 결재선을 처음부터 다시 거치게 되므로 반려 사유를 확인하고 내용을 수정한 뒤 다시 상신합니다.', ['문서', '반려', '받', '결재', '선', '처음', '거치', '반려', '사유', '확인', '내용', '수정', '뒤', '상신']),
(117, '전자결재·결재선', '전결 규정에 따라 100만 원 미만 지출은 팀장이, 1,000만 원 미만은 본부장이 최종 결재하며, 그 이상은 대표이사 결재가 필요합니다.', ['전결', '규정', '따르', '100', '만', '미만', '지출', '팀장', '1,000', '만', '미만', '본부장', '최종', '결재', '이상', '대표', '이사', '결재', '필요']),
(118, '전자결재·결재선', '결재자가 휴가나 출장 중이면 지정된 대결자가 대신 결재하며, 대결 내역은 문서 하단의 결재 이력에 표시됩니다.', ['결재', '휴가', '출장', '지정', '대결자', '대신', '결재', '대결', '내역', '문서', '하단', '결재', '이력', '표시']),
(119, '전자결재·결재선', '다른 부서의 확인이 필요한 문서는 합의 요청을 추가하며, 합의자가 7일 이상 응답하지 않으면 기안자가 담당 부서에 직접 문의합니다.', ['부서', '확인', '필요', '문서', '합의', '요청', '추가', '합의자', '7', '이상', '응답', '기안', '담당', '부서', '문의']),
(120, '전자결재·결재선', '첨부 파일은 파일당 20MB, 전체 100MB까지 올릴 수 있고, 개인정보가 포함된 파일은 암호를 설정해야 합니다.', ['첨부', '파일', '파일', '20', 'mb', '전체', '100', 'mb', '올리', '개인', '정보', '포함', '파일', '암호', '설정']),
(121, '전자결재·결재선', '상신한 문서는 다음 결재자가 열람하기 전에 \'회수\' 버튼으로 거둘 수 있으며, 회수한 문서는 임시 보관함에 저장됩니다.', ['상신', '문서', '다음', '결재', '열람', '전', '회수', '버튼', '거두', '회수', '문서', '임시', '보관', '함', '저장']),
(122, '전자결재·결재선', '승인이 끝난 문서는 5년간 전자결재 시스템에 보존되며, 영구 보존 문서는 문서 분류 코드를 별도로 지정해야 합니다.', ['승인', '끝나', '문서', '5', '전자', '결재', '시스템', '보존', '영구', '보존', '문서', '문서', '분류', '코드', '별도', '지정']),
(123, '전자결재·결재선', '모바일 앱에서도 결재와 반려가 가능하지만, 보안 등급이 높은 문서는 사내 PC에서만 열람할 수 있습니다.', ['모바일', '앱', '결재', '반려', '가능', '보안', '등급', '높', '문서', '사내', 'pc', '열람']),
(124, '망 분리 정책', '망 분리는 업무망과 인터넷망을 물리적으로 나누어 외부 위협이 업무 시스템으로 번지지 않게 하는 보안 정책이며, 모든 직원 PC에 적용됩니다.', ['망', '분리', '업무', '망', '인터넷', '망', '물리', '나누', '외부', '위협', '업무', '시스템', '번지', '보안', '정책', '직원', 'pc', '적용']),
(125, '망 분리 정책', '망을 분리한 이유는 인터넷에서 유입되는 악성코드가 업무 시스템으로 확산되는 것을 막고, 내부 자료의 외부 유출 경로를 줄이기 위해서입니다.', ['망', '분리', '이유', '인터넷', '유입', '악성', '코드', '업무', '시스템', '확산', '막', '내부', '자료', '외부', '유출', '경로', '줄이', '위하']),
(126, '망 분리 정책', '망 간 파일 이동은 자료 전송 시스템으로만 가능합니다. 망이 서로 다르면 USB나 메일로 직접 옮길 수 없고, 전송 신청서에 파일명과 반출 사유를 적어야 합니다.', ['망', '파일', '이동', '자료', '전송', '시스템', '가능', '망', '다르', 'usb', '메일', '옮기', '없', '전송', '신청서', '파일', '명', '반출', '사유', '적']),
(127, '망 분리 정책', '한쪽 망에서 만든 파일을 다른 망으로 보내면 악성코드 검사를 거친 뒤 팀장이 승인해야 전달되며, 승인 대기 중인 파일은 격리 영역에 보관됩니다.', ['한쪽', '망', '만들', '파일', '망', '보내', '악성', '코드', '검사', '거치', '뒤', '팀장', '승인', '전달', '승인', '대기', '파일', '격리', '영역', '보관']),
(128, '망 분리 정책', '인터넷망 PC에서는 외부 사이트와 웹 메일을 사용할 수 있지만, 사내 ERP나 전자결재에는 접속되지 않습니다.', ['인터넷망', 'pc', '외부', '사이트', '웹', '메일', '사용', '사내', 'erp', '전자', '결재', '접속']),
(129, '망 분리 정책', '업무망 PC에서는 외부 인터넷이 차단되며, 업무에 필요한 외부 사이트는 화이트리스트로 신청하면 열어 줍니다.', ['업무', '망', 'pc', '외부', '인터넷', '차단', '업무', '필요', '외부', '사이트', '화이트', '리스트', '신청', '열']),
(130, '망 분리 정책', '접속이 차단된 사이트를 열어야 하면 IT 헬프데스크에 URL과 업무 사유를 적어 요청하고, 보안팀 검토 후 3영업일 안에 결과를 알려 드립니다.', ['접속', '차단', '사이트', '열', 'it', '헬프', '데스크', 'url', '업무', '사유', '적', '요청', '보안', '팀', '검토', '후', '3', '영업일', '안', '결과', '알리']),
(131, '망 분리 정책', '망 분리 PC는 분기마다 보안 패치를 일괄 적용하며, 패치 기간에는 PC를 끄지 말고 재시작 안내가 나오면 따라야 합니다.', ['망', '분리', 'pc', '분기', '보안', '패치', '일괄', '적용', '패치', '기간', 'pc', '끄', '시작', '안내', '나오', '따르']),
(132, '망 분리 정책', '재택근무자는 VPN으로 업무망에 접속하며, 인터넷 검색은 개인 기기에서 하되 업무 자료를 개인 기기로 옮기면 안 됩니다.', ['재택', '근무자', 'vpn', '업무', '망', '접속', '인터넷', '검색', '개인', '기기', '업무', '자료', '개인', '기기', '옮기']),
(133, '망 분리 정책', '망 분리 예외 신청은 개발·보안 업무처럼 인터넷이 꼭 필요한 직무에 한해 부서장 승인과 보안팀 심사를 거쳐 1년 단위로 허용합니다.', ['망', '분리', '예외', '신청', '개발', '보안', '업무', '인터넷', '필요', '직무', '한하', '부서장', '승인', '보안', '팀', '심사', '거치', '1', '단위', '허용']),
(134, '망 분리 정책', '업무망과 인터넷망 PC는 모니터 하나를 공유하는 스위치로 전환하며, 케이블을 임의로 바꿔 꽂으면 안 됩니다.', ['업무', '망', '인터넷', '망', 'pc', '모니터', '하나', '공유', '스위치', '전환', '케이블', '임의', '바꾸', '꽂']),
(135, '비밀번호 정책', '비밀번호는 영문 대소문자, 숫자, 특수문자를 모두 포함해 12자 이상으로 설정해야 하며, 사전에 있는 단어나 사번은 사용할 수 없습니다.', ['비밀', '번호', '영문', '대소', '문자', '숫자', '특수', '문자', '포함', '12', '이상', '설정', '사전', '단어', '사', '사용', '없']),
(136, '비밀번호 정책', '비밀번호는 SSO 포털 우측 상단의 \'내 정보\' 메뉴에서 직접 바꿀 수 있으며, 현재 비밀번호는 입력해야 새로운 값이 저장됩니다.', ['비밀', '번호', 'sso', '포털', '우측', '상단', '정보', '메뉴', '바꾸', '비밀', '번호', '입력', '새롭', '값', '저장']),
(137, '비밀번호 정책', '비밀번호가 기억나지 않으면 헬프데스크 셀프서비스 페이지에서 본인 인증을 마친 뒤 초기화할 수 있으며, 임시 비밀번호는 로그인 직후 바꿔야 합니다.', ['비밀', '번호', '기억나', '헬프데스크', '셀프', '서비스', '페이지', '본인', '인증', '마치', '뒤', '초기', '임시', '비밀', '번호', '로그인', '직후', '바꾸']),
(138, '비밀번호 정책', '비밀번호를 90일마다 변경하는 것이 원칙이며, 변경 주기는 시스템의 보안 등급에 따라 다를 수 있습니다.', ['비밀', '번호', '90', '변경', '원칙', '변경', '주기', '시스템', '보안', '등급', '따르', '다르']),
(139, '비밀번호 정책', '최근 5회 이내에 사용한 비밀번호는 재사용할 수 없으며, 새 비밀번호의 앞 4자리가 이전과 같아도 거부됩니다.', ['최근', '5', '이내', '사용', '비밀번호', '사용', '없', '비밀번호', '앞', '4', '자리', '이전', '같', '거부']),
(140, '비밀번호 정책', '비밀번호 재사용 여부는 시스템이 이전 해시값과 비교해 확인하므로, 대소문자만 바꾸는 식의 변형은 인정되지 않습니다.', ['비밀번호', '사용', '여부', '시스템', '이전', '시', '값', '비교', '확인', '대소', '문자', '바꾸', '변형', '인정']),
(141, '비밀번호 정책', '비밀번호를 메신저나 메일로 공유하거나 포스트잇에 적어 모니터에 붙여 두는 것은 금지됩니다.', ['비밀번호', '메신저', '메일', '공유', '포스트잇', '적', '모니터', '붙이', '금지']),
(142, '비밀번호 정책', '개인용 비밀번호 관리 프로그램은 사내 지급 PC에 설치할 수 없으며, 보안팀이 승인한 사내 비밀번호 보관 도구만 사용할 수 있습니다.', ['개인', '비밀번호', '관리', '프로그램', '사내', '지급', 'pc', '설치', '없', '보안', '팀', '승인', '사내', '비밀', '번호', '보관', '도구', '사용']),
(143, '비밀번호 정책', 'OTP는 SSO 로그인 시 한 번 더 요구되며, 30초마다 새로운 번호가 생성되고 한 번 입력한 번호는 재사용할 수 없습니다. 시간이 지나면 새 번호로 다시 입력해야 합니다.', ['otp', 'sso', '로그인', '요구', '30', '새롭', '번호', '생성', '입력', '번호', '사용', '없', '시간', '지나', '번호', '입력']),
(144, '비밀번호 정책', '공용 계정은 원칙적으로 발급하지 않으며, 불가피하게 사용하는 경우 담당자가 사용 이력을 기록해야 합니다.', ['공용', '계정', '원칙', '발급', '불가피', '사용', '경우', '담당자', '사용', '이력', '기록']),
(145, '비밀번호 정책', '퇴사자의 계정은 퇴사일 당일 모든 접속 권한이 회수되며, 개인 파일은 30일 뒤 삭제됩니다.', ['퇴사', '계정', '퇴사', '당일', '접속', '권한', '회수', '개인', '파일', '30', '뒤', '삭제']),
(146, '개인정보 처리 지침', '개인정보 처리는 수집, 이용, 보관, 파기의 전 과정에서 법령과 사내 처리방침을 따라야 하며, 담당자는 처리 목적과 근거를 기록으로 남겨야 합니다.', ['개인', '정보', '처리', '수집', '이용', '보관', '파', '과정', '법령', '사내', '처리', '방침', '따르', '담당자', '처리', '목적', '근거', '기록', '남기']),
(147, '개인정보 처리 지침', '개인정보는 정보주체의 동의 없이 외부 업체에 제공할 수 없으며, 제공이 필요하면 제공 검토 요청서를 정보보호팀에 제출해 사전 승인을 받아야 합니다.', ['개인', '정보', '정보', '주체', '동의', '외부', '업체', '제공', '없', '제공', '필요', '제공', '검토', '요청서', '정보', '보호', '팀', '제출', '사전', '승인', '받']),
(148, '개인정보 처리 지침', '승인 후 개인정보가 담긴 파일을 외부로 보낼 때는 암호를 건 압축 파일로 전송하고, 암호는 파일과 다른 경로로 수신자에게 따로 전달해야 합니다.', ['승인', '후', '개인', '정보', '담기', '파일', '외부', '보내', '때', '암호', '걸', '압축', '파일', '전송', '암호', '파일', '경로', '수신자', '전달']),
(149, '개인정보 처리 지침', '고객 개인정보를 수집할 때는 서비스 제공에 꼭 필요한 항목만 최소한으로 받아야 하며, 주민등록번호는 법령에 근거가 없으면 수집할 수 없습니다.', ['고객', '개인', '정보', '수집', '때', '서비스', '제공', '필요', '항목', '최소한', '받', '주민', '등록', '번호', '법령', '근거', '없', '수집', '없']),
(150, '개인정보 처리 지침', '수집 목적이 달성된 개인정보를 계속 보관하려면 별도의 법적 근거가 있어야 하고, 보관 기간이 끝난 자료는 5영업일 안에 파기합니다.', ['수집', '목적', '달성', '개인', '정보', '보관', '별도', '법', '근거', '보관', '기간', '끝나', '자료', '5', '영업일', '안', '파기']),
(151, '개인정보 처리 지침', '전자 파일은 복구할 수 없는 방법으로 삭제하고, 종이 문서는 파쇄함에 넣어 파쇄하며, 파기 내역은 대장에 기록합니다.', ['전자', '파일', '복구', '없', '방법', '삭제', '종이', '문서', '파쇄', '함', '넣', '파쇄', '파', '내역', '대장', '기록']),
(152, '개인정보 처리 지침', '개인정보 유출이 의심되면 즉시 정보보호팀에 알려야 하며, 유출이 확인되면 72시간 이내에 정보주체에게 통지하고 관계 기관에 신고합니다.', ['개인', '정보', '유출', '의심', '즉시', '정보', '보호', '팀', '알리', '유출', '확인', '72', '이내', '정보', '주체', '통지', '관계', '기관', '신고']),
(153, '개인정보 처리 지침', '고객 개인정보에 접근할 수 있는 직원은 업무상 필요한 최소 인원으로 제한하고, 접근 기록은 1년간 보관합니다.', ['고객', '개인', '정보', '접근', '직원', '업무', '필요', '최소', '인원', '제한', '접근', '기록', '1', '간', '보관']),
(154, '개인정보 처리 지침', '개인정보가 화면에 표시된 상태로 자리를 비우면 안 되며, 5분 이상 자리를 비울 때는 화면 잠금을 설정해야 합니다.', ['개인', '정보', '화면', '표시', '상태', '자리', '비우', '5', '이상', '자리', '비우', '때', '화면', '잠금', '설정']),
(155, '개인정보 처리 지침', '고객이 자신의 정보를 열람하거나 삭제해 달라고 요청하면 접수 후 10일 이내에 처리하고 결과를 알려 줘야 합니다.', ['고객', '자신', '정보', '열람', '삭제', '요청', '접수', '후', '10', '이내', '처리', '결과', '알리']),
(156, '개인정보 처리 지침', '개인정보를 다루는 직원은 연 1회 이상 보호 교육을 받아야 하며, 이수 내역은 인사 시스템에 자동으로 기록됩니다.', ['개인', '정보', '다루', '직원', '연', '1', '이상', '보호', '교육', '받', '수', '내역', '인사', '시스템', '자동', '기록']),
(157, 'USB·외부 저장장치', 'USB 같은 외부 저장장치는 기본적으로 차단되며, 업무상 필요하면 포털의 \'IT > 보안 신청\' 메뉴에서 사용 승인 신청서를 작성해 부서장과 보안팀의 승인을 받아야 합니다.', ['usb', '같', '외부', '저장', '장치', '기본', '차단', '업무', '필요', '포털', 'it', '보안', '신청', '메뉴', '사용', '승인', '신청서', '작성', '부서장', '보안', '팀', '승인', '받']),
(158, 'USB·외부 저장장치', '승인이 나면 보안팀이 USB의 일련번호를 등록해 주며, 등록된 장치만 PC에서 인식됩니다. 사용 기간은 최대 6개월이고 연장하려면 다시 신청해야 합니다.', ['승인', '나', '보안', '팀', 'usb', '일련번호', '등록', '등록', '장치', 'pc', '인식', '사용', '기간', '최대', '6', '연장', '신청']),
(159, 'USB·외부 저장장치', '외부 저장장치에 파일을 담을 때의 암호화는 보안팀이 배포한 전용 프로그램으로 진행하며, 암호화 옵션을 켜지 않은 파일은 저장 단계에서 차단됩니다.', ['외부', '저장', '장치', '파일', '담', '때', '암호', '보안', '팀', '배포', '전용', '프로그램', '진행', '암호', '옵션', '켜', '파일', '저장', '단계', '차단']),
(160, 'USB·외부 저장장치', '전용 프로그램은 포털 소프트웨어 센터에서 설치하며, 암호화 설정은 USB를 연결한 뒤 프로그램의 \'보호 폴더 만들기\' 메뉴에서 진행합니다.', ['전용', '프로그램', '포털', '소프트웨어', '센터', '설치', '암호', '설정', 'usb', '연결', '뒤', '프로그램', '보호', '폴더', '만들', '메뉴', '진행']),
(161, 'USB·외부 저장장치', 'USB를 분실했거나 도난당하면 즉시 보안팀에 신고해야 하며, 저장되어 있던 파일의 종류를 함께 알려야 합니다.', ['usb', '분실', '도난', '즉시', '보안', '팀', '신고', '저장', '파일', '종류', '알리']),
(162, 'USB·외부 저장장치', '개인이 구입한 USB나 휴대용 SSD는 회사 PC에 연결할 수 없으며, 연결을 시도하면 보안 로그에 기록됩니다.', ['개인', '구입', 'usb', '휴대', 'ssd', '회사', 'pc', '연결', '없', '연결', '시도', '보안', '로그', '기록']),
(163, 'USB·외부 저장장치', '휴대 기기를 USB 케이블로 PC에 연결해 충전하는 것은 허용하지만, 파일 전송 모드는 차단됩니다.', ['휴대', '기기', 'usb', '케이블', 'pc', '연결', '충전', '허용', '파일', '전송', '모드', '차단']),
(164, 'USB·외부 저장장치', '승인 기간이 끝난 USB는 사용을 중지하고 보안팀에 등록 해지를 요청해야 하며, 해지하지 않으면 6개월간 인식되지 않습니다.', ['승인', '기간', '끝나', 'usb', '사용', '중지', '보안', '팀', '등록', '해지', '요청', '해지', '6', '인식']),
(165, 'USB·외부 저장장치', '고객 개인정보와 소스 코드는 어떤 경우에도 외부 저장장치에 저장할 수 없으며, 이를 어기면 징계 대상이 됩니다.', ['고객', '개인', '정보', '소스', '코드', '경우', '외부', '저장', '장치', '저장', '없', '어기', '징계', '대상']),
(166, 'USB·외부 저장장치', '외부 저장장치를 연결하면 PC가 자동으로 악성코드 검사를 하므로 검사가 끝날 때까지 장치를 뽑지 않아야 합니다.', ['외부', '저장', '장치', '연결', 'pc', '자동', '악성', '코드', '검사', '검사', '끝나', '때', '장치', '뽑']),
(167, 'USB·외부 저장장치', '개인 클라우드 저장소와 웹하드 사이트는 차단되어 있으며, 파일 공유가 필요하면 사내 협업 드라이브를 사용합니다.', ['개인', '클라우드', '저장소', '웹', '하드', '사이트', '차단', '파일', '공유', '필요', '사내', '협업', '드라이브', '사용']),
(168, '피싱 메일 신고', '피싱 메일은 발신자 주소를 위장해 결재 요청, 택배 안내, 보안 경고를 사칭하는 경우가 많으므로 링크를 누르기 전에 발신자 도메인을 확인해야 합니다.', ['피싱', '메일', '발신자', '주소', '위장', '결재', '요청', '택배', '안내', '보안', '경고', '사칭', '경우', '많', '링크', '누르', '전', '발신자', '도메인', '확인']),
(169, '피싱 메일 신고', '피싱이 의심되는 메일은 Outlook 상단의 \'피싱 신고\' 버튼을 눌러 보안팀으로 전달하며, 신고 즉시 해당 메일은 받은 편지함에서 격리됩니다.', ['피싱', '의심', '메일', 'outlook', '상단', '피싱', '신고', '버튼', '누르', '보안', '팀', '전달', '신고', '즉시', '해당', '메일', '받', '편지', '함', '격리']),
(170, '피싱 메일 신고', '버튼이 보이지 않으면 메일을 전달하지 말고 헬프데스크 메신저 채널에 발신자 주소와 받은 시각을 적어 보내 주세요. 신고는 24시간 접수됩니다.', ['버튼', '보이', '메일', '전달', '헬프데스크', '메신저', '채널', '발신자', '주소', '받', '시각', '적', '보내', '신고', '24', '접수']),
(171, '피싱 메일 신고', '의심스러운 링크를 이미 클릭했거나 첨부 파일을 열었다면 즉시 네트워크 연결을 끊고 보안팀 내선으로 연락해 지시를 받아야 합니다.', ['의심', '링크', '클릭', '첨부', '파일', '열', '즉시', '네트워크', '연결', '끊', '보안', '팀', '내선', '연락', '지시', '받']),
(172, '피싱 메일 신고', '정기 피싱 모의 훈련에서 의심 메일을 신고한 직원에게는 소정의 포인트를 지급하며, 포인트는 사내 복지몰에서 사용할 수 있습니다.', ['정기', '피싱', '모의', '훈련', '의심', '메일', '신고', '직원', '소정', '포인트', '지급', '포인트', '사내', '복지', '몰', '사용']),
(173, '피싱 메일 신고', '메일 제목에 [외부] 태그가 붙은 메일은 사외에서 온 메일이므로, 내부 직원을 사칭하는 내용이라면 특히 주의해야 합니다.', ['메일', '제목', '외부', '태그', '붙', '메일', '사외', '오', '메일', '내부', '직원', '사칭', '내용', '주의']),
(174, '피싱 메일 신고', '실행 파일이나 매크로가 포함된 문서가 첨부된 메일은 시스템이 자동으로 차단하며, 업무상 필요하면 보안팀에 해제를 요청합니다.', ['실행', '파일', '매크로', '포함', '문서', '첨부', '메일', '시스템', '자동', '차단', '업무', '필요', '보안', '팀', '해제', '요청']),
(175, '피싱 메일 신고', '비밀번호나 OTP 번호를 메일로 물어보는 경우는 모두 피싱이며, IT팀과 보안팀은 어떤 경우에도 이를 요구하지 않습니다.', ['비밀', '번호', 'otp', '번호', '메일', '물어보', '경우', '피싱', 'it', '팀', '보안', '팀', '경우', '요구']),
(176, '피싱 메일 신고', '문자메시지로 오는 택배 조회 링크나 인증 번호 요청도 피싱이 의심되면 눌러 보지 말고 지우는 것이 안전합니다.', ['문자', '메시지', '오', '택배', '조회', '링크', '인증', '번호', '요청', '피싱이', '의심', '누르', '지우', '안전']),
(177, '피싱 메일 신고', '신고 후 오탐으로 확인된 메일은 보안팀이 영업일 기준 1일 이내에 받은 편지함으로 복구해 드립니다.', ['신고', '후', '오탐', '확인', '메일', '보안', '팀', '영업일', '기준', '1', '이내', '받', '편지', '함', '복구']),
(178, '피싱 메일 신고', '피싱 모의 훈련은 분기마다 1회 진행되며, 훈련 메일을 클릭한 직원은 온라인 보안 교육을 추가로 이수해야 합니다.', ['피싱', '모의', '훈련', '분기', '1', '진행', '훈련', '메일', '클릭', '직원', '온라인', '보안', '교육', '추가', '이수']),
(179, 'VPN 접속 가이드', 'VPN은 업무용 노트북에 기본 설치되어 있으며, 설치되지 않은 경우 포털 소프트웨어 센터에서 사내 VPN 클라이언트를 내려받아 설치합니다.', ['vpn', '업무', '노트북', '기본', '설치', '설치', '경우', '포털', '소프트웨어', '센터', '사내', 'vpn', '클라이언트', '내려받', '설치']),
(180, 'VPN 접속 가이드', 'VPN 접속은 클라이언트를 실행한 뒤 SSO 계정으로 로그인하고, OTP 번호를 입력하면 완료됩니다.', ['vpn', '접속', '클라이언트', '실행', '뒤', 'sso', '계정', '로그인', 'otp', '번호', '입력', '완료']),
(181, 'VPN 접속 가이드', 'VPN 연결이 자주 끊기면 먼저 Wi-Fi 신호 세기를 확인하고, 클라이언트의 \'재연결\' 버튼을 눌러 보세요. 5GHz보다 2.4GHz 대역이 더 안정적인 경우도 있습니다.', ['vpn', '연결', '끊기', 'wi', 'fi', '신호', '세기', '확인', '클라이언트', '재연결', '버튼', '누르', '5', 'ghz', '2.4', 'ghz', '대역', '안정', '경우']),
(182, 'VPN 접속 가이드', '그래도 VPN 접속이 반복해서 끊기면 클라이언트를 최신 버전으로 업데이트하고, 끊긴 시각과 사용 중인 네트워크 종류를 적어 헬프데스크에 문의합니다.', ['vpn', '접속', '반복', '끊기', '클라이언트', '최신', '버전', '업데이트', '끊기', '시각', '사용', '네트워크', '종류', '적', '헬프데스크', '문의']),
(183, 'VPN 접속 가이드', 'VPN이 설치되지 않은 PC에서는 사내 시스템에 접속할 수 없으므로, 설치를 마친 뒤 재부팅을 한 번 해야 정상적으로 동작합니다.', ['vpn', '설치', 'pc', '사내', '시스템', '접속', '없', '설치', '마치', '뒤', '부팅', '정상', '동작']),
(184, 'VPN 접속 가이드', 'VPN 동시 접속은 계정당 1대로 제한되며, 다른 기기에서 접속하면 기존 연결이 끊어집니다. 연결이 자꾸 끊긴다면 같은 계정으로 다른 기기에 접속해 있지 않은지 확인하세요.', ['vpn', '동시', '접속', '계정', '1', '제한', '기기', '접속', '기존', '연결', '끊어지', '연결', '끊기', '같', '계정', '기기', '접속', '확인']),
(185, 'VPN 접속 가이드', 'VPN 접속 후 속도가 느리면 화상회의처럼 대역폭이 큰 작업은 사내에서 유선망을 사용하고, 불필요한 프로그램은 종료해 보세요.', ['vpn', '접속', '후', '속도', '느리', '화상', '회의', '대역', '폭', '크', '작업', '사내', '유선', '망', '사용', '필요', '프로그램', '종료']),
(186, 'VPN 접속 가이드', 'VPN 접속 중에는 개인 인터넷 서비스 접속이 느려질 수 있으며, 업무와 무관한 영상 시청은 자제해야 합니다.', ['vpn', '접속', '개인', '인터넷', '서비스', '접속', '느리', '업무', '무관하', '영상', '시청', '자제']),
(187, 'VPN 접속 가이드', 'VPN은 재택근무자, 출장자, 외근자에게만 허용되며, 사내에서는 VPN 없이 사내망을 이용합니다.', ['vpn', '재택근무', '출장', '외근', '허용', '사내', 'vpn', '사내', '망', '이용']),
(188, 'VPN 접속 가이드', 'VPN 접속 시 \'인증 실패\'가 표시되면 SSO 계정이 잠겼거나 OTP 시간이 어긋난 경우가 많으므로 SSO 상태와 기기 시간을 먼저 확인하세요.', ['vpn', '접속', '인증', '실패', '표시', 'sso', '계정', '잠기', 'otp', '시간', '어긋나', '경우', '많', 'sso', '상태', '기기', '시간', '확인']),
(189, 'VPN 접속 가이드', 'VPN 접속 기록은 보안팀이 6개월간 보관하며, 비정상 접속이 탐지되면 계정이 일시 정지될 수 있습니다.', ['vpn', '접속', '기록', '보안', '팀', '6', '간', '보관', '정상', '접속', '탐지', '계정', '일시', '정지']),
(190, 'Outlook 메일 사용', 'Outlook 사서함은 기본 50GB이며, 용량이 90%를 넘으면 경고창이 표시되고 100%가 되면 새 메일을 받을 수 없습니다.', ['outlook', '사서함', '기본', '50', 'gb', '용량', '90', '넘', '경고', '창', '표시', '100', '가', '메일', '받', '없']),
(191, 'Outlook 메일 사용', 'Outlook 사서함이 가득 찼다면 지운 편지함을 비우고 오래된 대용량 메일은 로컬 보관함으로 옮겨 용량을 확보합니다. 그래도 부족하면 헬프데스크에 증설을 요청할 수 있습니다.', ['outlook', '사서함', '차', '지우', '편지', '함', '비우', '용량', '메일', '로컬', '보관', '함', '옮기', '용량', '확보', '그렇', '부족', '헬프데스크', '증설', '요청']),
(192, 'Outlook 메일 사용', 'Outlook 첨부는 파일 합계 20MB까지이므로 그보다 큰 파일은 압축하거나 사내 드라이브 링크로 보내야 하며, 한도를 넘으면 전송 단계에서 오류가 표시됩니다.', ['outlook', '첨부', '파일', '합계', '20', 'mb', '크', '파일', '압축', '사내', '드라이브', '링크', '보내', '한도', '넘', '전송', '단계', '오류', '표시']),
(193, 'Outlook 메일 사용', '20MB를 넘는 파일은 Outlook 첨부 화면에서 \'클라우드 파일 첨부\'를 선택해 사내 드라이브 링크로 보내면 되고, 수신자 권한은 \'보기 전용\'이 기본입니다.', ['20', 'mb', '넘', '파일', 'outlook', '첨부', '화면', '클라우드', '파일', '첨부', '선택', '사내', '드라이브', '링크', '보내', '수신자', '권한', '보', '전용', '기본']),
(194, 'Outlook 메일 사용', 'Outlook 자동 완성 목록에 잘못된 주소가 나오면 해당 주소에 마우스를 올리고 X 표시를 눌러 삭제할 수 있습니다.', ['outlook', '자동', '완성', '목록', '주소', '나오', '해당', '주소', '마우스', '올리', 'x', '표시', '누르', '삭제']),
(195, 'Outlook 메일 사용', 'Outlook 메일 서명은 \'파일 > 옵션 > 메일\' 메뉴에서 설정하며, 사내 표준 서명 양식은 포털 서식 보관함에 있습니다.', ['outlook', '메일', '서명', '파일', '옵션', '메일', '메뉴', '설정', '사내', '표준', '서명', '양식', '포털', '서식', '보관']),
(196, 'Outlook 메일 사용', '휴가나 출장 중에는 Outlook의 \'자동 회신\' 기능으로 부재 안내 문구를 설정해 두고, 복귀일에 반드시 해제해야 합니다.', ['휴가', '출장', 'outlook', '자동', '회신', '기능', '부', '재', '안내', '문구', '설정', '복귀', '일', '해제']),
(197, 'Outlook 메일 사용', '메일이 도착하지 않았다면 먼저 \'정크 메일함\'을 확인하고, 거기에도 없으면 발신자에게 재발송을 요청하거나 헬프데스크에 수신 로그 조회를 요청합니다.', ['메일', '도착', '정크', '메일', '함', '확인', '없', '발신자', '발송', '요청', '헬프데스크', '수신', '로그', '조회', '요청']),
(198, 'Outlook 메일 사용', 'Outlook이 시작되지 않거나 \'프로필을 로드할 수 없습니다\' 메시지가 나오면 제어판의 메일 설정에서 새 프로필을 만들어 다시 연결합니다.', ['outlook', '시작', '프로필', '로드', '없', '메시지', '나오', '제어판', '메일', '설정', '프로필', '만들', '연결']),
(199, 'Outlook 메일 사용', '규칙 기능으로 특정 발신자의 메일을 폴더에 자동 분류할 수 있으며, 규칙이 지나치게 많으면 시작 속도가 느려질 수 있습니다.', ['규칙', '기능', '특정', '발신자', '메일', '폴더', '자동', '분류', '규칙', '지나치', '많', '시작', '속도', '느리']),
(200, 'Outlook 메일 사용', '오프라인 모드에서는 새 메일을 받을 수 없으므로, 화면 하단에 \'연결 끊김\' 표시가 보이면 네트워크 상태를 확인한 뒤 \'오프라인 작업\'을 해제합니다.', ['오프라인', '모드', '메일', '받', '없', '화면', '하단', '연결', '끊기', '표시', '보이', '네트워크', '상태', '확인', '뒤', '오프라인', '작업', '해제']),
(201, 'Outlook 메일 사용', 'Outlook 일정에서 회의 초대를 보낼 때는 \'일정 도우미\' 탭으로 참석자들이 모두 가능한 시간을 먼저 확인할 수 있습니다.', ['outlook', '일정', '회의', '초대', '보내', '때', '일정', '도우미', '탭', '참석자', '가능', '시간', '확인']),
(202, 'SSO·계정 잠김', '로그인에 5회 연속 실패하면 보안을 위해 계정 잠금이 걸리며, 별도 조치를 하지 않아도 30분이 지나면 자동으로 해제됩니다.', ['로그인', '5', '연속', '실패', '보안', '위하', '계정', '잠금', '걸리', '별도', '조치', '30', '지나', '자동', '해제']),
(203, 'SSO·계정 잠김', '잠긴 계정을 바로 사용해야 하면 헬프데스크 셀프서비스 페이지에서 본인 인증 후 직접 잠금 해제를 하거나, 헬프데스크에 전화해 해제를 요청합니다.', ['잠기', '계정', '사용', '헬프데스크', '셀프', '서비스', '페이지', '본인', '인증', '후', '잠금', '해제', '헬프', '데스크', '전화', '해제', '요청']),
(204, 'SSO·계정 잠김', 'SSO로 한 번 로그인하면 전자결재, ERP, 메일, Teams, 경비 정산 시스템에 다시 로그인하지 않고 이용할 수 있습니다.', ['sso', '로그인', '전자', '결재', 'erp', '메일', 'teams', '경비', '정산', '시스템', '로그인', '이용']),
(205, 'SSO·계정 잠김', 'SSO 연동 대상에 없는 시스템은 별도 계정이 필요하며, 연동 목록은 SSO 포털 첫 화면의 \'내 서비스\'에서 확인할 수 있습니다.', ['sso', '연동', '대상', '없', '시스템', '별도', '계정', '필요', '연동', '목록', 'sso', '포털', '화면', '서비스', '확인']),
(206, 'SSO·계정 잠김', 'SSO 로그인 세션은 8시간 유지되며, 퇴근 후에 로그아웃하지 않아도 자정에 자동으로 종료됩니다.', ['sso', '로그인', '세션', '8', '유지', '퇴근', '후', '로그', '아웃', '자정', '자동', '종료']),
(207, 'SSO·계정 잠김', '신규 입사자의 SSO 계정은 입사 전날 사번을 기반으로 생성되며, 초기 안내는 개인 메일로 발송됩니다.', ['신규', '입사자', 'sso', '계정', '입사', '전날', '사번', '기반', '생성', '초기', '내', '개인', '메일', '발송']),
(208, 'SSO·계정 잠김', '휴직자 계정은 휴직 시작일에 정지되고 복직일에 활성화되며, 정지 기간의 메일은 전달되지 않습니다.', ['휴직', '계정', '휴직', '시작', '일', '정지', '복직', '일', '활성', '정지', '기간', '메일', '전달']),
(209, 'SSO·계정 잠김', 'OTP 등록은 SSO 포털의 \'보안 설정\'에서 하며, 휴대 기기를 바꾸면 헬프데스크에서 본인 확인 후 OTP 등록을 초기화해야 합니다.', ['otp', '등록', 'sso', '포털', '보안', '설정', '휴대', '기기', '바꾸', '헬프데스크', '본인', '확인', '후', 'otp', '등록', '초기']),
(210, 'SSO·계정 잠김', 'PC 화면은 5분간 입력이 없으면 자동으로 잠기며, 잠긴 화면은 윈도우 로그인 정보로 해제합니다.', ['pc', '화면', '5', '간', '입력', '없', '자동', '잠기', '잠기', '화면', '윈도우', '로그인', '정보', '해제']),
(211, 'SSO·계정 잠김', '계정 잠금 이력은 보안팀이 월 1회 점검하며, 반복되는 잠금은 비정상 접근 시도로 판단해 조사할 수 있습니다.', ['계정', '잠금', '이력', '보안', '팀', '월', '1', '점검', '반복', '잠', '금', '정상', '접근', '시도', '판단', '조사']),
(212, 'SSO·계정 잠김', '부서를 이동하면 SSO 권한은 이동일에 일괄 재설정되며, 이전 부서의 시스템 접근 권한은 자동으로 회수됩니다.', ['부서', '이동', 'sso', '권한', '이동', '일', '일괄', '설정', '이전', '부서', '시스템', '접근', '권한', '자동', '회수']),
(213, '프린터·복합기 사용', '본관과 별관 각 층에는 복합기가 있으며, 복합기 위치와 모델 정보는 사내 포털의 \'비품 > 복합기 안내\'에서 확인할 수 있습니다.', ['본관', '별관', '층', '복합기', '복합기', '위치', '모델', '정보', '사내', '포털', '품', '복합기', '안내', '확인']),
(214, '프린터·복합기 사용', '복합기를 처음 쓰는 PC에서는 사원증을 복합기에 태그한 뒤 안내 화면의 QR을 스캔해 출력 프로그램을 설치하면 사용할 수 있습니다.', ['복합기', '처음', '쓰', 'pc', '사원', '증', '복합기', '태그', '뒤', '안내', '화면', 'qr', '스캔', '출력', '프로그램', '설치', '사용']),
(215, '프린터·복합기 사용', '보안 출력을 사용하면 출력 문서가 복합기에 보관되며, 복합기 앞에서 사원증을 태그해야 인쇄되므로 출력물이 방치되지 않습니다.', ['보안', '출력', '사용', '출력', '문서', '복합기', '보관', '복합기', '앞', '사원', '증', '태그', '인쇄', '출력', '물', '방치']),
(216, '프린터·복합기 사용', '프린터는 용지가 걸리면 화면에 걸림 위치가 표시되므로, 해당 덮개를 열고 걸린 용지를 천천히 당겨 빼야 합니다. 힘으로 잡아당기면 부품이 손상될 수 있습니다.', ['프린터', '용지', '걸리', '화면', '걸리', '위치', '표시', '해당', '덮개', '열', '걸리', '용지', '당기', '빼', '힘', '잡아당기', '부품', '손상']),
(217, '프린터·복합기 사용', '걸린 용지를 모두 제거한 뒤에도 프린터의 오류 표시등이 꺼지지 않으면 전원을 껐다 켜고, 그래도 안 되면 본체 라벨의 모델명 사진과 함께 헬프데스크에 접수해 주세요.', ['걸리', '용지', '제거', '뒤', '프린터', '오류', '표시', '등', '꺼지', '전원', '끄', '켜', '본체', '라벨', '모델명', '사진', '헬프데스크', '접수']),
(218, '프린터·복합기 사용', '프린터가 출력 대기열에서 멈춘 경우에는 인쇄 대기 창에서 문서를 삭제한 뒤 다시 출력하세요. 대기열이 계속 쌓이면 PC를 재부팅합니다.', ['프린터', '출력', '대기', '열', '멈추', '경우', '인쇄', '대기', '창', '문서', '삭제', '뒤', '출력', '대기', '열', '쌓이', 'pc', '부팅']),
(219, '프린터·복합기 사용', '토너가 부족하다는 메시지가 표시되면 총무팀에 토너 교체를 요청하고, 교체는 총무팀 담당자가 진행합니다.', ['토너', '부족', '메시지', '표시', '총무', '팀', '토너', '교체', '요청', '교체', '총무', '팀', '담당자', '진행']),
(220, '프린터·복합기 사용', '컬러 출력은 장당 비용이 높아 외부 제출용 문서에만 허용되며, 월 50장을 넘으면 팀장 승인이 필요합니다.', ['컬러', '출력', '비용', '높', '외부', '제출', '문서', '허용', '월', '50', '넘', '팀장', '승인', '필요']),
(221, '프린터·복합기 사용', '출력 비용 절감을 위해 기본 설정은 흑백 양면 인쇄이며, 단면이 필요하면 인쇄 창의 옵션에서 변경할 수 있습니다.', ['출력', '비용', '절감', '위하', '기본', '설정', '흑백', '양면', '인쇄', '단면', '필요', '인쇄', '창의', '옵션', '변경']),
(222, '프린터·복합기 사용', '스캔한 문서는 본인의 사내 메일로 전송되며, 개인정보가 포함된 문서는 스캔 후 복합기에 남은 기록을 삭제해야 합니다.', ['스캔', '문서', '본인', '사내', '메일', '전송', '개인', '정보', '포함', '문서', '스캔', '후', '복합기', '남', '기록', '삭제']),
(223, '프린터·복합기 사용', '개인 노트북에서는 복합기에 출력할 수 없으며, 출력이 필요하면 업무용 PC에서 출력하거나 문서를 업무용 PC로 옮겨야 합니다.', ['개인', '노트북', '복합기', '출력', '없', '출력', '필요', '업무', 'pc', '출력', '문서', '업무', 'pc', '옮기']),
(224, '노트북 지급·반납', '노트북은 입사 첫날 IT팀이 지급하며, 직무에 따라 일반형, 개발자용 고성능형, 영업용 경량형 중에서 배정됩니다.', ['노트북', '입사', '첫날', 'it', '팀', '지급', '직무', '따르', '일반', '개발자', '성능', '영업', '경량', '배정']),
(225, '노트북 지급·반납', '노트북 반납 시에는 포털에서 반납 신청을 올리고, 개인 파일을 사내 협업 드라이브로 옮겨 백업한 뒤 IT 헬프데스크에 직접 가져와야 합니다.', ['노트북', '반납', '포털', '반납', '신청', '올리', '개인', '파일', '사내', '협업', '드라이브', '옮기', '백업', '뒤', 'it', '헬프데스크', '가져오']),
(226, '노트북 지급·반납', '반납한 노트북은 IT팀이 상태를 점검하고 데이터를 완전히 삭제한 뒤 인수증을 발급하며, 인수증을 받아야 반납이 완료됩니다.', ['반납', '노트북', 'it', '팀', '상태', '점검', '데이터', '삭제', '뒤', '인수', '증', '발급', '인수증', '받', '반납', '완료']),
(227, '노트북 지급·반납', '노트북 교체 주기는 4년이며, 교체 대상자는 IT팀이 사전에 안내하고 새 장비의 수령 일정을 조율합니다.', ['노트북', '교체', '주기', '4', '교체', '대상자', 'it', '팀', '사전', '안내', '장비', '수령', '일정', '조율']),
(228, '노트북 지급·반납', '노트북을 분실하거나 도난당하면 즉시 보안팀과 IT팀에 신고하고, 경찰 신고 접수증을 제출해야 원격 삭제와 재지급이 진행됩니다.', ['노트북', '분실', '도난', '즉시', '보안', '팀', 'it', '팀', '신고', '경찰', '신고', '접수', '증', '제출', '원격', '삭제', '지급', '진행']),
(229, '노트북 지급·반납', '노트북이 고장 나면 헬프데스크에 수리를 접수하고, 수리 기간에는 임시 노트북을 대여해 드립니다.', ['노트북', '고장', '나', '헬프데스크', '수리', '접수', '수리', '기간', '임시', '노트북', '대여']),
(230, '노트북 지급·반납', '지급받은 노트북에는 디스크 암호화와 백신이 기본 설정되어 있으며, 임의로 해제하거나 다른 운영체제를 설치하면 안 됩니다.', ['지급', '노트북', '디스크', '암호', '백신', '기본', '설정', '임의', '해제', '운영', '체제', '설치']),
(231, '노트북 지급·반납', '노트북 외관에 스티커를 붙이는 것은 허용되지만, 자산 번호 라벨을 가리거나 떼어 내면 안 되고 자산 조사 때 번호를 확인받아야 합니다.', ['노트북', '외관', '스티커', '붙이', '허용', '자산', '번호', '라벨', '가리', '떼', '자산', '조사', '때', '번호', '확인', '받']),
(232, '노트북 지급·반납', '노트북이 파손된 경우 고의나 중과실이 아니면 비용이 청구되지 않지만, 반복해서 파손되면 사유서를 제출해야 합니다.', ['노트북', '파손', '경우', '고의', '중과실', '비용', '청구', '반복', '파손', '사유서', '제출']),
(233, '노트북 지급·반납', '노트북을 사외로 가져갈 때는 케이블 잠금 장치와 파우치를 사용하고, 차량에 두고 내리지 않도록 주의해야 합니다.', ['노트북', '사외', '가져가', '때', '케이블', '잠금', '장치', '파우치', '사용', '차량', '두', '내리', '주의']),
(234, '노트북 지급·반납', '노트북 배터리가 부풀거나 충전이 되지 않으면 사용을 중단하고 헬프데스크에 접수하며, 배터리 교체는 무상으로 진행됩니다.', ['노트북', '배터리', '부풀', '충전', '사용', '중단', '헬프데스크', '접수', '배터리', '교체', '무상', '진행']),
(235, 'Wi-Fi 이용 안내', '사내 Wi-Fi는 직원용 CORP와 방문자용 GUEST 두 가지이며, 직원용은 SSO 계정으로 인증하고 사내 시스템에 바로 접속할 수 있습니다.', ['사내', 'wi', 'fi', '직원', 'corp', '방문자', 'guest', '직원용', 'sso', '계정', '인증', '사내', '시스템', '접속']),
(236, 'Wi-Fi 이용 안내', '처음 연결할 때는 Wi-Fi 목록에서 CORP를 선택하고 사번과 SSO 비밀번호를 입력한 뒤 인증서 설치 안내에 동의해야 합니다.', ['처음', '연결', '때', 'wi', 'fi', '목록', 'corp', '선택', '사', 'sso', '비밀번호', '입력', '뒤', '인증서', '설치', '안내', '동의']),
(237, 'Wi-Fi 이용 안내', 'GUEST 네트워크는 인터넷만 이용할 수 있고 사내 시스템에는 접속되지 않으며, 외부 손님에게는 하루 단위로 발급되는 접속 코드를 안내합니다.', ['guest', '네트워크', '인터넷', '이용', '사내', '시스템', '접속', '외부', '손', '하루', '단위', '발급', '접속', '코드', '안내']),
(238, 'Wi-Fi 이용 안내', '신호가 약한 곳에서는 가까운 공유기로 자동 전환되지 않을 수 있으므로, 자리를 옮긴 뒤에는 Wi-Fi를 껐다 켜 보세요.', ['신호', '약하', '곳', '가깝', '공유', '자동', '전환', '자리', '옮기', '뒤', 'wi', 'fi', '끄', '키']),
(239, 'Wi-Fi 이용 안내', 'Wi-Fi에 연결되었지만 인터넷이 되지 않으면 Wi-Fi를 끊었다가 다시 연결하고, 계속되면 헬프데스크에 접속 위치를 알려 주세요.', ['wi', 'fi', '연결', '인터넷', 'wi', 'fi', '끊', '연결', '계속', '헬프데스크', '접속', '위치', '알리']),
(240, 'Wi-Fi 이용 안내', '개인 스마트 기기는 GUEST 네트워크만 이용할 수 있으며, 개인 기기를 CORP에 연결하려는 시도는 차단됩니다.', ['개인', '스마트', '기기', 'guest', '네트워크', '이용', '개인', '기기', 'corp', '연결', '시도', '차단']),
(241, 'Wi-Fi 이용 안내', '회의실에서는 다수가 동시에 접속하므로 대용량 파일 다운로드나 업데이트는 자리로 돌아와서 하는 것이 좋습니다.', ['회의실', '다수', '동시', '접속', '용량', '파일', '다운로드', '업데이트', '자리', '돌아오', '좋']),
(242, 'Wi-Fi 이용 안내', 'Wi-Fi 이용 기록은 접속 기기와 시간이 보안팀 로그에 6개월간 보관되며, 감사나 사고 조사 외의 다른 목적으로는 사용하지 않습니다.', ['wi', 'fi', '이용', '기록', '접속', '기기', '시간', '보안', '팀', '로그', '6', '간', '보관', '감사', '사고', '조사', '목적', '사용']),
(243, 'Wi-Fi 이용 안내', '개인용 휴대용 공유기나 핫스팟을 사내에서 켜는 것은 금지되며, 발견되면 보안팀이 장비를 회수할 수 있습니다.', ['개인', '휴대', '공유', '핫', '스팟', '사내', '켜', '금지', '발견', '보안', '팀', '장비', '회수']),
(244, 'Wi-Fi 이용 안내', '5GHz 대역은 속도가 빠르지만 벽을 잘 통과하지 못하므로, 회의실이나 복도 끝에서는 2.4GHz 대역이 더 안정적입니다.', ['5', 'ghz', '대역', '속도', '빠르', '벽', '통과', '회의실', '복도', '끝', '2.4', 'ghz', '대역', '안정']),
(245, 'Wi-Fi 이용 안내', 'Wi-Fi 공유기 설치 요청은 총무팀이 아니라 IT팀 헬프데스크에 접수하며, 현장 실사 후 설치 일정이 안내됩니다.', ['wi', 'fi', '공유', '설치', '요청', '총무', '팀', 'it', '팀', '헬프데스크', '접수', '현장', '실사', '후', '설치', '일정', '안내']),
(246, 'Teams 메신저', 'Teams는 사내 표준 메신저로, 1:1 채팅, 그룹 채팅, 채널 대화, 음성·영상 통화를 한 곳에서 사용할 수 있으며 SSO 계정으로 로그인합니다.', ['teams', '사내', '표준', '메신저', '채팅', '그룹', '채팅', '채널', '대화', '음성', '영상', '통화', '곳', '사용', 'sso', '계정', '로그인']),
(247, 'Teams 메신저', 'Teams 알림이 오지 않으면 프로필 사진 옆 설정의 \'알림\' 메뉴에서 채팅과 멘션 알림이 켜져 있는지 먼저 확인해 보세요.', ['teams', '알림', '오', '프로필', '사진', '옆', '설정', '알리', '메뉴', '채팅', '멘션', '알리', '켜지', '확인']),
(248, 'Teams 메신저', 'Windows의 집중 지원 기능이 켜져 있으면 Teams 알림이 표시되지 않으므로, 집중 지원을 끄거나 Teams를 우선 순위 목록에 추가해 두어야 합니다.', ['windows', '집중', '지원', '기능', '켜', 'teams', '알림', '표시', '집중', '지원', '끄', 'teams', '르', '순위', '목록', '추가']),
(249, 'Teams 메신저', 'Teams의 새 팀은 왼쪽 메뉴의 \'만들기\' 버튼으로 시작하며, 공개 범위는 \'조직 전체\' 또는 \'비공개\' 중에서 선택합니다.', ['teams', '팀', '왼쪽', '메뉴', '만들', '버튼', '시작', '공개', '범위', '조직', '전체', '공개', '선택']),
(250, 'Teams 메신저', '새로 만든 팀의 이름은 \'부서명_목적\' 형식으로 정해야 하고, 팀이 생성된 뒤에는 소유자를 2명 이상 지정해야 합니다.', ['만들', '팀', '이름', '부서', '명', '목적', '형식', '정하', '팀', '생성', '뒤', '소유자', '2', '이상', '지정']),
(251, 'Teams 메신저', '팀을 삭제하면 90일 동안 관리자가 복원할 수 있으며, 소유자가 아닌 구성원은 삭제 권한이 없습니다.', ['팀', '삭제', '90', '동안', '관리자', '복원', '소유자', '구성원', '삭제', '권한', '없']),
(252, 'Teams 메신저', '채널은 업무 주제별로 나누며, 비공개 채널의 파일은 해당 채널 구성원만 볼 수 있으니 민감한 자료는 비공개 채널에서 공유하세요.', ['채널', '업무', '주제', '나누', '공개', '채널', '파일', '해당', '채널', '구성원', '보', '민감', '자료', '공개', '채널', '공유']),
(253, 'Teams 메신저', '상태 표시는 \'대화 가능\', \'다른 용무 중\', \'방해 금지\'를 직접 바꿀 수 있고, 회의 중에는 자동으로 \'다른 용무 중\'으로 바뀝니다.', ['상태', '표시', '대화', '가능', '용무', '방해', '금지', '바꾸', '회의', '자동', '용무', '바뀌']),
(254, 'Teams 메신저', 'Teams에서 공유한 파일은 사내 협업 드라이브에 저장되며, 외부 게스트와 파일을 공유하려면 보안팀의 사전 승인이 필요합니다.', ['teams', '공유', '파일', '사내', '협업', '드라이브', '저장', '외부', '게스트', '파일', '공유', '보안', '팀', '사전', '승인', '필요']),
(255, 'Teams 메신저', '채팅 기록은 1년간 보관된 뒤 자동으로 삭제되며, 업무상 필요한 대화는 별도 문서로 정리해 두어야 합니다.', ['채팅', '기록', '1', '간', '보관', '뒤', '자동', '삭제', '업무', '필요', '대화', '별도', '문서', '정리']),
(256, 'Teams 메신저', '외부 업체 직원을 팀에 초대하려면 소유자가 게스트 초대 요청서를 작성해 보안팀 승인을 받아야 하며, 승인된 게스트는 90일 뒤 자동 만료됩니다.', ['외부', '업체', '직원', '팀', '초대', '소유자', '게스트', '초대', '요청서', '작성', '보안', '팀', '승인', '받', '승인', '게스트', '90', '뒤', '자동', '만료']),
(257, 'ERP 오류 코드', 'ERP 오류가 발생하면 화면 하단에 \'ERP-\'로 시작하는 오류 코드가 표시되며, 코드를 알려 주면 헬프데스크가 원인을 더 빨리 찾을 수 있습니다.', ['erp', '오류', '발생', '화면', '하단', 'erp', '시작', '오류', '코드', '표시', '코드', '알리', '헬프데스크', '원인', '찾']),
(258, 'ERP 오류 코드', 'ERP-4012는 로그인 세션이 만료되었다는 뜻이며, ERP 화면을 모두 닫고 SSO 포털에서 다시 로그인하면 대부분 해결됩니다.', ['erp', '4012', '로그인', '세션', '만료', '뜻', 'erp', '화면', '닫', 'sso', '포털', '로그인', '대부분', '해결']),
(259, 'ERP 오류 코드', '다시 로그인해도 ERP-4012가 반복되면 브라우저 캐시와 쿠키를 삭제하고 Edge 브라우저로 접속해 보며, 그래도 해결되지 않으면 오류 화면을 캡처해 ERP 담당자에게 문의합니다.', ['로그인', 'erp', '4012', '반복', '브라우저', '캐시', '쿠키', '삭제', 'edge', '브라우저', '접속', '해결', '오류', '화면', '캡처', 'erp', '담당자', '문의']),
(260, 'ERP 오류 코드', 'ERP-4013은 조회나 입력 권한이 없다는 의미이며, 권한 신청서를 작성해 부서장 승인을 받은 뒤 ERP 담당자에게 요청해야 합니다.', ['erp', '4013', '조회', '입력', '권한', '없', '의미', '권한', '신청서', '작성', '부서장', '승인', '받', '뒤', 'erp', '담당자', '요청']),
(261, 'ERP 오류 코드', 'ERP-4021이 표시되면 전표의 필수 항목이 비어 있다는 뜻이므로, 빨간색으로 표시된 입력란을 모두 채운 뒤 다시 저장합니다.', ['erp', '4021', '표시', '전표', '필수', '항목', '비', '뜻', '빨간색', '표시', '입력', '란', '채우', '뒤', '저장']),
(262, 'ERP 오류 코드', 'ERP-4030은 같은 증빙 번호로 이미 등록된 전표가 있다는 의미이며, 중복 입력인지 확인한 뒤 기존 전표를 수정하거나 삭제해야 합니다.', ['erp', '4030', '같', '증빙', '번호', '등록', '전표', '의미', '중복', '입력', '확인', '뒤', '기존', '전표', '수정', '삭제']),
(263, 'ERP 오류 코드', 'ERP-5001은 회계 마감 기간에는 해당 월의 전표를 입력할 수 없다는 오류이며, 마감 해제는 재무팀에 요청해야 합니다.', ['erp', '5001', '회계', '마감', '기간', '해당', '월', '전표', '입력', '없', '오류', '마감', '해제', '재무', '팀', '요청']),
(264, 'ERP 오류 코드', 'ERP는 Edge와 Chrome 최신 버전에서만 정상 동작하며, 호환성 보기가 켜져 있으면 일부 화면이 표시되지 않을 수 있습니다.', ['erp', 'edge', 'chrome', '최신', '버전', '정상', '동작', '호환성', '보기', '켜지', '일부', '화면', '표시']),
(265, 'ERP 오류 코드', 'ERP는 매월 첫째 일요일 새벽 2시부터 5시까지 정기 점검으로 접속이 제한되며, 점검 일정은 포털 공지로 안내합니다.', ['erp', '첫째', '일요일', '새벽', '2', '5', '정기', '점검', '접속', '제한', '점검', '일정', '포털', '공지', '안내']),
(266, 'ERP 오류 코드', 'ERP 담당자 문의는 헬프데스크 티켓의 \'ERP\' 카테고리로 접수하며, 오류 코드와 화면 캡처, 발생 시각을 함께 적어야 처리가 빨라집니다.', ['erp', '담당자', '문의', '헬프데스크', '티켓', 'erp', '카테고리', '접수', '오류', '코드', '화면', '캡처', '발생', '시각', '적', '처리', '빠르']),
(267, 'ERP 오류 코드', 'ERP에서 저장한 전표는 실시간으로 회계 시스템에 반영되지 않고 10분 단위로 일괄 처리되므로, 저장 직후 조회되지 않아도 오류가 아닙니다.', ['erp', '저장', '전표', '실시간', '회계', '시스템', '반영', '10', '단위', '일괄', '처리', '저장', '직후', '조회', '오류']),
(268, '업무용 폰·MDM', '업무용 폰은 영업, 현장 지원, 비상 연락 직무에 한해 지급하며, 신청은 부서장 승인 후 IT팀에 접수합니다.', ['업무', '폰', '영업', '현장', '지원', '비상', '연락', '직무', '한', '지급', '신청', '부서장', '승인', '후', 'it', '팀', '접수']),
(269, '업무용 폰·MDM', '개인 폰은 MDM 등록과 보안 정책 동의를 마친 경우에만 사내 메일과 메신저를 사용할 수 있으며, 등록하지 않은 개인 폰에서는 사내 계정에 로그인할 수 없습니다.', ['개인', '폰', 'mdm', '등록', '보안', '정책', '동의', '마치', '경우', '사내', '메일', '메신저', '사용', '등록', '개인', '폰', '사내', '계정', '로그인', '없']),
(270, '업무용 폰·MDM', '개인 폰에서 사내 메일을 쓰려면 MDM 등록을 먼저 해야 하며, 등록은 헬프데스크 안내 페이지의 QR을 스캔하면 5분 안에 끝납니다.', ['개인', '폰', '사내', '메일', '쓰', 'mdm', '등록', '등록', '헬프데스크', '안내', '페이지', 'qr', '스캔', '5', '안', '끝나']),
(271, '업무용 폰·MDM', '업무용 폰을 분실하면 즉시 IT팀에 알려야 하며, 보안팀이 MDM으로 원격 잠금과 데이터 삭제를 실행합니다. 신고가 늦어지면 요금과 정보 유출에 대한 책임을 질 수 있습니다.', ['업무', '폰', '분실', '즉시', 'it', '팀', '알리', '보안', '팀', 'mdm', '원격', '잠금', '데이터', '삭제', '실행', '신고', '늦', '요금', '정보', '유출', '대하', '책임', '지']),
(272, '업무용 폰·MDM', 'MDM 앱은 기기를 처음 받았을 때 설치되어 있으며, 삭제하거나 비활성화하면 사내 시스템 접속이 즉시 차단됩니다.', ['mdm', '앱', '기기', '처음', '받', '때', '설치', '삭제', '활성', '사내', '시스템', '접속', '차단']),
(273, '업무용 폰·MDM', '업무용 폰의 월 통신 요금은 회사가 부담하며, 해외 로밍과 부가 서비스 요금은 개인 사용분을 본인이 부담합니다.', ['업무', '폰', '월', '통신', '요금', '회사', '부담', '해외', '로밍', '부가', '서비스', '요금', '개인', '사용', '본인', '부담']),
(274, '업무용 폰·MDM', '업무용 폰에는 승인된 사내 스토어의 프로그램만 설치할 수 있으며, 게임이나 SNS 프로그램은 MDM 정책으로 차단됩니다.', ['업무', '폰', '승인', '사내', '스토어', '프로그램', '설치', '게임', 'sns', '프로그램', 'mdm', '정책', '차단']),
(275, '업무용 폰·MDM', '업무용 폰은 24개월 사용 후 교체할 수 있으며, 반납하는 기기는 초기화한 뒤 IT팀에 전달해야 합니다.', ['업무', '폰', '24', '사용', '후', '교체', '반납', '기기', '초기', '뒤', 'it', '팀', '전달']),
(276, '업무용 폰·MDM', '업무용 폰으로 촬영한 고객 정보나 화이트보드 사진은 업무가 끝나면 즉시 삭제해야 하며, 개인 클라우드에는 저장하지 않습니다.', ['업무', '폰', '촬영', '고객', '정보', '화이트보드', '사진', '업무', '끝나', '즉시', '삭제', '개인', '클라우드', '저장']),
(277, '업무용 폰·MDM', '업무용 폰은 6자리 이상의 화면 잠금을 설정해야 하며, 10회 틀리면 기기가 초기화됩니다.', ['업무', '폰', '6', '자리', '이상', '화면', '잠금', '설정', '10', '틀리', '기기', '초기']),
(278, '업무용 폰·MDM', '해외 출장 시 업무용 폰의 로밍은 출발 3일 전까지 IT팀에 신청해야 하며, 데이터 로밍 한도는 일 5GB입니다.', ['해외', '출장', '업무', '폰', '로밍', '출발', '3', '전', 'it', '팀', '신청', '데이터', '로밍', '한도', '일', '5', 'gb']),
(279, '소프트웨어 설치 요청', '업무용 소프트웨어 설치는 포털의 \'소프트웨어 설치 요청\' 메뉴에서 신청하며, 제품명, 버전, 사용 목적, 라이선스 보유 여부를 입력해야 합니다.', ['업무', '소프트웨어', '설치', '포털', '소프트웨어', '설치', '요청', '메뉴', '신청', '제품', '명', '버전', '사용', '목적', '라이선스', '보유', '여부', '입력']),
(280, '소프트웨어 설치 요청', '설치 요청은 IT팀의 보안 검토를 거쳐 승인되며, 승인되면 원격 설치가 자동으로 진행되거나 소프트웨어 센터에 설치 항목이 추가됩니다. 검토에는 영업일 기준 3일이 걸립니다.', ['설치', '요청', 'it', '팀', '보안', '검토', '거치', '승인', '승인', '원격', '설치', '자동', '진행', '소프트웨어', '센터', '설치', '항목', '추가', '검토', '영업일', '기준', '3', '걸리']),
(281, '소프트웨어 설치 요청', '승인된 표준 소프트웨어는 별도 요청 없이 소프트웨어 센터에서 바로 설치할 수 있으며, 표준 목록은 센터 첫 화면에서 확인할 수 있습니다.', ['승인', '표준', '소프트웨어', '별도', '요청', '소프트웨어', '센터', '설치', '표준', '목록', '센터', '화면', '확인']),
(282, '소프트웨어 설치 요청', '설치 중 0x80070005 오류가 나타나면 접근 권한이 없다는 뜻입니다. 사내 PC는 일반 사용자 권한으로 운영되므로 직접 해결하지 말고 헬프데스크에 오류 코드와 소프트웨어 이름을 알려 주세요.', ['설치', '0', 'x', '80070005', '오류', '나타나', '접근', '권한', '없', '뜻', '사내', 'pc', '일반', '사용자', '권한', '운영', '해결', '헬프데스크', '오류', '코드', '소프트웨어', '이름', '알리']),
(283, '소프트웨어 설치 요청', '소프트웨어 센터에서 설치할 때 0x80070005가 나오면 센터의 임시 폴더 권한이 꼬인 경우가 많으므로 PC를 재부팅한 뒤 다시 시도하고, 계속되면 헬프데스크에 알려 주세요.', ['소프트웨어', '센터', '설치', '때', '0', 'x', '80070005', '나오', '센터', '임시', '폴더', '권한', '꼬이', '경우', '많', 'pc', '부팅', '뒤', '시도', '계속', '헬프데스크', '알리']),
(284, '소프트웨어 설치 요청', '설치 중 0x80070057 오류가 나타나면 설치 파일이 손상되었을 수 있으므로 같은 파일을 다시 내려받아 시도해 보고, 반복되면 헬프데스크에 알려 주세요.', ['설치', '0', 'x', '80070057', '오류', '나타나', '설치', '파일', '손상', '같', '파일', '내리', '받', '시도', '반복', '헬프데스크', '알리']),
(285, '소프트웨어 설치 요청', '윈도우 업데이트에서 0x800F0922가 표시되면 저장 공간이나 시스템 예약 파티션이 부족한 경우가 많으므로, 불필요한 파일을 정리한 뒤 다시 업데이트하세요.', ['윈도우', '업데이트', '0', 'x', '800', 'f', '0922', '표시', '저장', '공간', '시스템', '예약', '파티션', '부족', '경우', '많', '필요', '파일', '정리', '뒤', '업데이트']),
(286, '소프트웨어 설치 요청', '토렌트 클라이언트, 원격 제어 도구, 개인용 클라우드 동기화 프로그램은 보안 정책상 사용이 금지되어 있으며, 발견되면 즉시 삭제됩니다.', ['토렌트', '클라이언트', '원격', '제어', '도구', '개인', '클라우드', '동기', '프로그램', '보안', '정책', '사용', '금지', '발견', '즉시', '삭제']),
(287, '소프트웨어 설치 요청', '소프트웨어 업데이트는 매주 화요일 밤에 자동으로 배포되며, 재시작 안내가 나오면 퇴근 전에 PC를 재시작해야 합니다.', ['소프트웨어', '업데이트', '화요일', '밤', '자동', '배포', '시작', '안내', '나오', '퇴근', '전', 'pc', '시작']),
(288, '소프트웨어 설치 요청', '더 이상 쓰지 않는 소프트웨어는 제어판에서 직접 삭제하거나 헬프데스크에 삭제를 요청할 수 있으며, 라이선스는 즉시 회수되어 다른 직원에게 재배정됩니다.', ['이상', '쓰', '소프트웨어', '제어', '판', '삭제', '헬프데스크', '삭제', '요청', '라이선스', '즉시', '회수', '직원', '배정']),
(289, '소프트웨어 설치 요청', '윈도우 업데이트는 IT팀이 승인한 버전만 배포되며, 업데이트를 임의로 미루거나 중단하면 사내 네트워크 접속이 제한될 수 있습니다.', ['윈도우', '업데이트', 'it', '팀', '승인', '버전', '배포', '업데이트', '임의', '미루', '중단', '사내', '네트워크', '접속', '제한']),
(290, '사내 모바일 앱 안내', '사내 모바일 앱은 근태, 식권, 주차 등록, 전자결재 알림 네 가지이며, 모두 업무용 폰의 사내 스토어에서 내려받을 수 있습니다.', ['사내', '모바일', '앱', '근태', '식권', '주차', '등록', '전자', '결재', '알림', '업무', '폰', '사내', '스토어', '내려받']),
(291, '사내 모바일 앱 안내', '사내 앱은 업무용 폰의 사내 스토어에서 자동 업데이트가 기본으로 켜져 있으며, 수동으로 하려면 스토어의 \'업데이트\' 탭에서 항목 옆 버튼을 누릅니다.', ['사내', '앱', '업무', '폰', '사내', '스토어', '자동', '업데이트', '기본', '켜', '수동', '스토어', '업데이트', '탭', '항목', '옆', '버튼', '누르']),
(292, '사내 모바일 앱 안내', '사내 앱이 업데이트되지 않고 \'지원하지 않는 버전\' 메시지가 나오면 스토어에서 삭제한 뒤 다시 설치하고, 로그인은 SSO 계정으로 새로 진행합니다.', ['사내', '앱', '업데이트', '지원', '버전', '메시지', '나오', '스토어', '삭제', '뒤', '설치', '로그인', 'sso', '계정', '진행']),
(293, '사내 모바일 앱 안내', '사내 앱을 처음 설치할 때는 사내 스토어에 SSO 계정으로 로그인한 뒤 원하는 항목을 선택하고, 권한 허용 안내에서 \'허용\'을 눌러야 정상 동작합니다.', ['사내', '앱', '처음', '설치', '때', '사내', '스토어', 'sso', '계정', '로그인', '뒤', '원하', '항목', '선택', '권한', '허용', '안', '허용', '누르', '정상', '동작']),
(294, '사내 모바일 앱 안내', '근태 앱은 출근과 퇴근 시각을 위치 확인과 함께 기록하며, 재택근무일에는 위치 확인 없이 \'재택\' 버튼으로 기록합니다.', ['근태', '앱', '출근', '퇴근', '시각', '위치', '확인', '기록', '재택', '근무', '일', '위치', '확인', '재택', '버튼', '기록']),
(295, '사내 모바일 앱 안내', '식권 앱은 점심과 저녁 식사를 하루 각 1회까지 결제할 수 있고, 월 한도는 급여일 기준으로 초기화됩니다.', ['식권', '앱', '점심', '저녁', '식사', '하루', '1', '결제', '월', '한도', '급여', '기준', '초기']),
(296, '사내 모바일 앱 안내', '주차 등록은 앱에서 차량 번호를 입력해 신청하며, 방문 차량은 방문 예약 시스템에서 따로 등록해야 합니다.', ['주차', '등록', '앱', '차량', '번호', '입력', '신청', '방문', '차량', '방문', '예약', '시스템', '등록']),
(297, '사내 모바일 앱 안내', '전자결재 알림은 결재 요청이 도착했을 때만 전송되며, 알림 설정은 화면 우측 상단의 톱니바퀴 아이콘에서 바꿀 수 있습니다.', ['전자', '결재', '알림', '결재', '요청', '도착', '때', '전송', '알림', '설정', '화면', '우측', '상단', '톱니바퀴', '아이콘', '바꾸']),
(298, '사내 모바일 앱 안내', '사내 앱은 SSO 계정으로 한 번 로그인하면 30일간 유지되며, 기기를 바꾸거나 MDM 등록이 해제되면 다시 로그인해야 합니다.', ['사내', '앱', 'sso', '계정', '로그인', '30', '유지', '기기', '바꾸', 'mdm', '등록', '해제', '로그인']),
(299, '사내 모바일 앱 안내', '사내 앱에서 오류가 생기면 설정에서 캐시를 지우고 다시 실행해 보고, 해결되지 않으면 오류 화면을 캡처해 헬프데스크에 보내 주세요.', ['사내', '앱', '오류', '생기', '설정', '캐시', '지우', '실행', '해결', '오류', '화면', '캡처', '헬프데스크', '보내']),
(300, '사내 모바일 앱 안내', '퇴사하거나 업무용 폰을 반납하면 사내 앱의 로그인 정보가 원격으로 삭제되며, 저장된 근태 기록은 서버에 그대로 보존됩니다.', ['퇴사', '업무', '폰', '반납', '사내', '앱', '로그인', '정보', '원격', '삭제', '저장', '근태', '기록', '서버', '보존']);
INSERT INTO queries (qid, fcase, question, morphemes, relevant, note) VALUES
(1, 'particle', '출장비를 미리 받으려면 어떻게 해야 하나요?', ['출장비', '받'], [24, 25], 'query 출장비를 / chunks 출장비는, 출장비가'),
