('kiwipiepy', '0.24.0'),
('kiwipiepy_model', '0.24.0'),
('pos_rule', 'Kiwi().tokenize(text); keep tags whose base (before \'-\') is in {NNG, NNP, NR, SL, SN, SH, XR, VV, VA}; lowercase; drop forms {하, 되, 있, 어떻}; keep order and duplicates');
