-- GENERATED by gen_data.py from data/*.jsonl -- do not edit; re-run
--   uv run usecase/korean-rag-tokenizers/gen_data.py
--
-- Morphemes come from Kiwi, outside ClickHouse:
--   kiwipiepy 0.24.0, kiwipiepy_model 0.24.0
--   POS rule: Kiwi().tokenize(text); keep tags whose base (before '-') is in {NNG, NNP, NR, SL, SN, SH, XR, VV, VA}; lowercase; drop forms {하, 되, 있, 어떻}; keep order and duplicates.
-- The same rule produced every `morphemes` column below. A different Kiwi
-- version or model can change them; lab_meta records what was used.

CREATE DATABASE IF NOT EXISTS korean_rag;
USE korean_rag;

DROP TABLE IF EXISTS chunks_src;
CREATE TABLE chunks_src
(
    id         UInt32,
    doc        String,
    body       String,
    morphemes  Array(String)
)
ENGINE = MergeTree ORDER BY id;

DROP TABLE IF EXISTS queries;
CREATE TABLE queries
(
    qid        UInt16,
    fcase      LowCardinality(String),
    question   String,
    morphemes  Array(String),
    relevant   Array(UInt32),
    note       String
)
ENGINE = MergeTree ORDER BY qid;

DROP TABLE IF EXISTS phrases;
CREATE TABLE phrases
(
    pid        UInt8,
    fcase      String,
    phrase     String,
    morphemes  Array(String)
)
ENGINE = MergeTree ORDER BY pid;

DROP TABLE IF EXISTS lab_meta;
CREATE TABLE lab_meta
(
    key    String,
    value  String
)
ENGINE = MergeTree ORDER BY key;
